QCU_T("es", "ethiqueLegislation", {
  "0": ["¿Cómo calificar el antiguo modelo de comunicación asistencial, anterior al consentimiento a los cuidados y al paciente socio autónomo?",["Un modelo paternalista, en el que el profesional decide por el paciente.","Un modelo de colaboración, centrado en un paciente autónomo.","Un modelo autonomista, fundado en el consentimiento del paciente."],["El antiguo modelo era paternalista: el profesional decidía en lugar del paciente.","El paciente socio corresponde al modelo reciente, no al antiguo.","La autonomía y el consentimiento surgieron después: no caracterizan el antiguo modelo."]],
  "1": ["El encarnizamiento terapéutico comprende:",["Prolongar artificialmente la vida.","Proteger los derechos de los pacientes","Una muerte digna"],["El curso lo asimila a la obstinación irrazonable: el paciente con una afección incurable sufre tratamientos que solo prolongan dolorosamente su agonía.","Es precisamente lo contrario: la obstinación irrazonable atenta contra la dignidad y el bienestar del paciente.","La muerte digna se obtiene renunciando a la obstinación irrazonable; es su contrario, no su definición."]],
  "2": ["¿Quién puede consentir al tratamiento médico en un menor de más de 16 años?",["El médico","El propio menor","El padre únicamente"],["El profesional valora la capacidad del menor entre los 12 y los 16 años, pero nunca consiente en lugar del paciente.","A partir de los 16 años se reputa al menor capaz de consentir por sí solo; el consentimiento por representación deja de ser la regla.","Antes de los 16 años el consentimiento lo dan los representantes legales, en plural, y no uno solo de los progenitores."]],
  "3": ["¿Qué es el «sufrimiento grave, crónico e imposibilitante» según la ley de eutanasia?",["Todo dolor moderado","Una enfermedad leve pero crónica","Un dolor constante, imposibilitante e intolerable"],["Un dolor moderado sigue siendo accesible a los tratamientos y no cumple el criterio exigido.","La cronicidad no basta: la afección debe ser grave e incurable y comprometer el pronóstico vital.","La ley exige un sufrimiento ligado a la afección, refractario a los tratamientos o insoportable según el propio paciente."]],
  "4": ["¿Cuál es el criterio principal para la asistencia médica urgente de un menor?",["El interés superior del menor","La elección de los padres","La voluntad del médico"],["El curso establece que el interés superior del menor prevalece sobre cualquier otro interés legítimo.","La voluntad parental cede cuando se opone al interés superior del menor, en particular en una urgencia vital.","El profesional actúa bajo el principio de beneficencia en beneficio del paciente; no impone su propia voluntad."]],
  "5": ["¿Qué condición no es necesaria para solicitar la ayuda para morir?",["Ser mayor de edad","Tener una enfermedad leve","Ser residente legal"],["La mayoría de edad figura entre las cinco condiciones de acceso a la ayuda para morir que enumera el curso.","La ley exige al contrario una afección grave e incurable que comprometa el pronóstico vital, en fase avanzada o terminal.","La residencia regular y estable forma parte de las condiciones de acceso que prevé la ley."]],
  "6": ["La negativa parental a un tratamiento vital para un menor:",["Debe respetarse","Debe aprobarla un juez de inmediato","Constituye una situación de riesgo"],["El respeto de la decisión parental cede ante el deber de asistencia y el estado de necesidad.","El profesional debe actuar primero para salvaguardar la vida; la intervención judicial no condiciona la actuación urgente.","La negativa de los representantes legales a un tratamiento necesario para salvaguardar la vida se trata como una situación de riesgo, que se comunica para que se tome una decisión en el interés del menor."]],
  "7": ["En el delito de revelación de secretos…",["La información privada del paciente debe protegerse siempre.","Un profesional sanitario incurrirá en la misma pena que un ciudadano.","El simple acceso a la historia clínica se considera un delito grave."],["La confidencialidad cubre toda información conocida con ocasión de la asistencia, sin límite de tiempo ni de objeto.","La condición de profesional sanitario es al contrario una circunstancia agravante, al ser el secreto una obligación ligada a la función.","Lo que se castiga es la revelación o el acceso no autorizado, no el acceso legítimo de un profesional que participa en la asistencia."]],
  "8": ["En caso de error de diagnóstico, hay responsabilidad si:",["El diagnóstico es correcto pero mal explicado","No se han realizado las pruebas necesarias","El tratamiento no era eficaz"],["Un defecto de explicación corresponde al deber de información, no al error de diagnóstico.","Omitir las pruebas que imponía la lex artis constituye un incumplimiento del deber de diligencia, es decir una imprudencia que compromete la responsabilidad.","La asistencia constituye una obligación de medios: la ausencia de resultado no es en sí culposa."]],
  "9": ["¿Qué es la lex artis en la responsabilidad sanitaria?",["Una ley específica","Una norma de ética","Una práctica reconocida científicamente"],["No es un texto legal, sino un estándar profesional al que se remiten los jueces.","Corresponde al saber técnico y no al ámbito normativo de la ética.","La lex artis designa el conjunto de las reglas del arte admitidas por la ciencia, cuyo respeto condiciona la exoneración de responsabilidad."]],
  "10": ["¿Qué diferencia existe entre la responsabilidad contractual y la extracontractual?",["El tipo de relación entre paciente y profesional","La edad del paciente","El lugar de la intervención"],["El curso opone la relación contractual, nacida del recurso a los servicios del profesional, a la relación extracontractual, en la que ningún contrato vincula a las partes.","La edad no entra en la calificación del vínculo jurídico entre profesional y paciente.","El lugar no determina la naturaleza del vínculo: tanto una como otra puede darse en un centro o en la consulta."]],
  "11": ["La responsabilidad civil nace cuando hay:",["Buena fe","Daño causado por negligencia","Contrato escrito"],["La buena fe no crea ninguna obligación de reparar; al contrario, puede atenuar la apreciación de la culpa.","Supone una acción negligente, una culpa y un perjuicio que debe repararse mediante una indemnización.","La responsabilidad puede ser extracontractual, sin que ningún escrito vincule a las partes."]],
  "12": ["En la mayoría de sus intervenciones en materia de Salud, la obligación del profesional es:",["Una obligación de resultados","La obligación de proponer únicamente el mejor tratamiento, según el criterio del médico","Una obligación de medios"],["No se compromete ninguna responsabilidad cuando las técnicas disponibles se han empleado correctamente, incluso sin curación.","El criterio no es la preferencia personal del profesional, sino la conformidad con la lex artis.","El curso enuncia que la asistencia sanitaria constituye una obligación de medios y no de resultados."]],
  "13": ["Un profesional sanitario puede negar la asistencia únicamente si:",["Existe un riesgo real y objetivo para él","No está de acuerdo con el paciente","No dispone de material"],["El curso reserva el abandono de los pacientes al solo caso de un riesgo grave, real y objetivo para la persona del profesional.","El desacuerdo no autoriza la negativa a asistir; el profesional debe garantizar la asistencia urgente.","La falta de material obliga a derivar al paciente, no a negar toda asistencia."]],
  "14": ["¿En qué consiste la despersonalización de la historia clínica?",["En no incluir anotaciones personales referidas al paciente","En eliminar de la historia clínica entregada a docentes o investigadores los datos que no les son necesarios","En omitir las patologías anteriores del paciente que no están relacionadas con la enfermedad actual"],["Las anotaciones subjetivas sí figuran en la historia; solo son objeto de reserva cuando el paciente accede a ella.","El acceso con fines de investigación o de docencia obliga a separar los datos de identificación de los datos clínicos para garantizar el anonimato.","La historia debe al contrario seguir siendo fiable y completa para permitir conocer el estado de salud real."]],
  "15": ["¿Quién controla el proceso de eliminación de las anotaciones subjetivas de las historias clínicas?",["El paciente, si lo exige","El superior del profesional que las ha escrito","El profesional que las ha escrito"],["El derecho de acceso del paciente se detiene precisamente ante la reserva de las anotaciones subjetivas.","La reserva es un derecho propio del autor de las anotaciones, no una prerrogativa jerárquica.","El curso reconoce a los profesionales que han participado en la elaboración de la historia el derecho a oponer la reserva de sus anotaciones subjetivas."]],
  "16": ["La prescripción de eutanasia puede realizarla:",["El médico responsable","Cualquier enfermera","El equipo asistencial entero"],["La ley encomienda la conducción del procedimiento al médico responsable: es él quien recibe la solicitud, verifica las condiciones y prescribe.","El profesional de enfermería interviene en particular para verificar la confirmación de la voluntad del paciente, pero no prescribe.","El equipo se asocia al procedimiento y a la verificación colegiada, sin que la prescripción sea un acto colectivo."]],
  "17": ["¿Funciones de un fisioterapeuta propietario de una clínica frente a las historias clínicas, según la Ley Orgánica de Protección de Datos?",["Debe garantizar la seguridad y la conservación de las historias","Debe cumplimentar la historia clínica y revisar el trabajo de los fisioterapeutas que trabajan bajo su responsabilidad","Debe garantizar la seguridad y la conservación de las historias y revisar el trabajo de los fisioterapeutas bajo su responsabilidad"],["La Ley Orgánica de Protección de Datos pone a cargo del responsable del tratamiento la seguridad de los datos personales y su conservación; es la única obligación que se deriva de ese texto.","Cumplimentar la historia y supervisar al equipo son deberes clínicos y jerárquicos, ajenos a la ley de protección de datos.","La propuesta mezcla una obligación derivada de la LOPD con una función de supervisión que no se deriva de ella; la pregunta versa únicamente sobre el fundamento de esa ley."]],
  "18": ["¿Cuál es la pena por no socorrer a una persona en peligro manifiesto sin riesgo para uno mismo?",["6 meses de prisión","1 año de prisión","De 3 a 12 meses de multa"],["La privación de libertad se reserva a las formas agravadas, no a la simple negativa a asistir.","Una pena de prisión supone una circunstancia agravante, como haber causado uno mismo el peligro.","El curso remite al código penal, que castiga con multa la simple negativa a socorrer a una persona en peligro manifiesto y grave."]],
  "19": ["La objeción de conciencia de un profesional sanitario debe ser:",["Anticipada y por escrito","Verbal","Aceptada por el médico responsable"],["La objeción de conciencia debe declararse por anticipado y por escrito, para que la organización pueda garantizar la continuidad de la asistencia.","Una declaración oral no permite fechar la objeción ni organizar la sustitución del profesional.","La objeción es un derecho propio del profesional: no está sometida a la autorización de un colega."]],
  "20": ["¿Cuál es la pena para un conductor que abandona a una víctima de accidente sin justificación?",["3 meses de multa","Hasta 4 años de prisión","Ninguna si no hay testigos"],["La multa sanciona la negativa a socorrer ordinaria, no la del causante del accidente.","Haber causado uno mismo el accidente agrava el delito de omisión del deber de socorro y eleva la sanción de la multa a la prisión.","La ausencia de testigos no suprime la infracción: lo que se castiga es la indiferencia ante el peligro."]],
  "21": ["En el delito de omisión del deber de socorro…",["No existen distintos tipos de castigo en ese delito.","No tendrá ninguna obligación si no sabe cómo ayudar.","El bien jurídico protegido es la solidaridad humana."],["La sanción varía según las circunstancias, en particular cuando el autor ha provocado él mismo el peligro.","El curso precisa que la conducta sigue siendo punible incluso si la ayuda hubiera resultado inútil; hay que al menos avisar a los servicios de emergencia.","El curso presenta la asistencia a una persona en peligro como una obligación moral, legal y deontológica que se impone a todo ciudadano: lo que se protege es la solidaridad."]],
  "22": ["¿Cuándo se considera que no se ha cometido ningún delito de intrusismo?",["Cuando un profesional realiza actividades que no pertenecen exclusivamente a su profesión","Cuando un profesional ejerce una profesión sin titulación","Cuando un profesional realiza sin supervisión actividades reservadas a profesionales que exceden sus competencias"],["El intrusismo supone invadir actos reservados: una actividad no exclusiva puede realizarse sin cometer la infracción.","Ejercer sin título es el caso más característico del intrusismo profesional, que la deontología obliga a denunciar.","Exceder las propias competencias en actos reservados constituye precisamente intrusismo."]],
  "23": ["¿Qué funciones debe asumir el trabajador por cuenta ajena frente a las historias clínicas?",["Respetar el carácter confidencial de la historia clínica","Respetar el carácter confidencial de la historia clínica y cumplimentarla de forma legible","Cumplimentar la historia clínica de forma legible"],["Exacto pero incompleto: la confidencialidad no exime de cumplimentar efectivamente la historia.","Ambos deberes se acumulan: el secreto profesional protege el contenido, y el paciente tiene derecho a que se consigne información fiable y actualizada.","Exacto pero incompleto: llevar la historia no dice nada de la obligación de secreto que protege su contenido."]],
  "24": ["¿Qué es un valor?",["Lo que una persona o una comunidad juzga lo bastante importante para buscarlo","Una regla de conducta que la conciencia moral tiene por obligatoria","Una prerrogativa reconocida a toda persona por su condición humana"],["El valor se define por la importancia que se reconoce a algo, lo que justifica que se promueva y se privilegie.","Esa es la definición de la norma moral, que se deriva del valor sin confundirse con él.","Esa es la definición de un derecho; el valor le es anterior y le sirve de fuente."]],
  "25": ["¿Cuál de estas propuestas no corresponde a una forma que puede adoptar un valor?",["Un estado de ánimo buscado por sí mismo, como la paz o la seguridad","Una sanción dictada por la autoridad en caso de incumplimiento de la norma","Una conducta como decir la verdad o proteger a los más vulnerables"],["Un estado mental buscado por sí mismo es efectivamente una de las formas del valor.","La sanción corresponde al derecho y no es una forma que revista el valor.","Una conducta derivada de un objeto o de un estado mental se cuenta entre esas formas."]],
  "26": ["¿Cuál es el papel de los valores en la toma de decisión?",["Aportar una respuesta directa y univoca a cada dilema que se plantee","Eximir de analizar la situación aplicando una regla ya fijada","Ayudar a reflexionar y a jerarquizar las prioridades, sin zanjar el dilema"],["Si así fuera, ningún conflicto de valores sería posible y la deliberación resultaría inútil.","Ese es el funcionamiento de la norma moral seguida sin examen, no el del valor.","Son herramientas de reflexión: iluminan las soluciones posibles sin decidir en lugar del profesional."]],
  "27": ["¿De dónde proceden los valores de una persona?",["De la familia, de la religión, del medio social, de la educación y del género","Únicamente de la educación recibida en la infancia, y después permanecen fijos","Únicamente del marco legal vigente en el país donde la persona reside"],["Esas influencias cruzadas construyen los valores personales, cuya jerarquía se desplaza a lo largo de la vida.","La importancia que se concede a los valores personales evoluciona a lo largo de toda la existencia.","La ley encuadra las conductas, pero no constituye el origen de los valores individuales."]],
  "28": ["¿Qué es un conflicto de valores?",["La oposición entre un valor personal y una disposición legal vigente","La oposición, en una situación dada, de dos valores igualmente legítimos","La incapacidad de una persona de identificar cuáles son sus propios valores"],["Esa es la divergencia entre ética y legalidad, que constituye otra configuración.","Como ambos merecen ser respetados, se necesita un análisis profundo para determinar la conducta que hay que seguir.","La incertidumbre no es un conflicto: este supone dos valores identificados y opuestos."]],
  "29": ["¿Por qué exige un conflicto de valores un análisis profundo?",["Siempre existe un valor superior y basta con conseguir identificarlo","La ley designa en cada caso el valor que debe prevalecer sobre el otro","Ningún valor prima de forma absoluta, y debe respetarse la pluralidad cultural"],["Precisamente, ningún valor absoluto prevalece sobre los demás en todas las circunstancias.","La ley suele callar o resultar ambigua sobre esos arbitrajes, lo que vuelve necesaria la reflexión.","La ausencia de jerarquía absoluta y la coexistencia de escalas de valores diferentes impiden toda solución automática."]],
  "30": ["¿Cuál es la relación entre los valores y los derechos?",["No son lo mismo, pero los valores están en el origen de los derechos","Son dos términos equivalentes que designan exactamente la misma realidad","Son los derechos reconocidos los que generan los valores de una sociedad"],["Los derechos formalizan jurídicamente lo que los valores han señalado antes como importante.","Confundirlos equivaldría a ignorar que el valor precede al reconocimiento jurídico.","El orden es el inverso: es el valor reconocido el que impulsa a crear el derecho correspondiente."]],
  "31": ["¿Qué se busca al hablar de valores universales?",["Los valores mayoritarios en los países más poblados del planeta","Lo que vale para todos los individuos en virtud de nuestra humanidad compartida","Los valores impuestos a los Estados por los tratados que han ratificado"],["Una mayoría estadística no fundamenta la universalidad, que se apoya en la humanidad común.","La universalidad se apoya en lo que es común a la humanidad, más allá de los contextos particulares.","El valor universal precede al instrumento jurídico, que no hace más que expresarlo."]],
  "32": ["¿Qué significa la etimología de la palabra «moral»?",["Viene del griego *ethos*, que designa el carácter de una persona","Viene del latín *norma*, que designa la regla y la escuadra","Viene del latín *mores*, que designa las costumbres de una sociedad"],["Esa es la etimología de «ética», que remite a la reflexión sobre las costumbres más que a las costumbres mismas.","La norma designa la regla que produce la moral, no el origen de la palabra en sí.","La moral es el conjunto de las normas y reglas de conducta propias de una sociedad dada."]],
  "33": ["¿De dónde se deriva el carácter obligatorio de la norma moral?",["Del valor que nosotros mismos le reconocemos","De una ley que la impone y prevé una sanción","De la autoridad de quien la ha formulado"],["La obligación moral no viene de una coacción exterior, sino de la adhesión al valor que traduce.","Ese es el mecanismo de la regla jurídica, cuya fuerza viene de la coacción pública.","Si la obligación dependiera de la autoridad de su autor, sería disciplinaria y no moral."]],
  "34": ["¿Cuál de estas afirmaciones sobre la moral es correcta?",["Solo existe una, idéntica en todo tiempo y en todo lugar","No existe una sola: las prácticas varían según las épocas y los lugares","Solo atañe a la esfera privada y nunca a las conductas sociales"],["La historia muestra al contrario una pluralidad de morales según las épocas y las sociedades.","Lo que se tenía por correcto en la Antigüedad puede juzgarse inaceptable hoy.","La moral versa precisamente sobre las reglas de conducta propias de una sociedad."]],
  "35": ["¿Qué actitud caracteriza a la persona que se limita a seguir la moral de su entorno?",["Cuestiona las reglas, delibera y después elige libremente ajustarse a ellas","Rechaza las reglas establecidas en nombre de sus convicciones personales","Conoce las reglas y las acepta de inmediato, sin interponer reflexión alguna"],["Ese recorrido reflexivo define al contrario el proceder ético.","El rechazo supone también una toma de posición, y por tanto un examen previo.","Esa adhesión sin examen es propia de la moral, a la que se suscribe sin interrogarla."]],
  "36": ["¿Por qué se dice que la moral es heterónoma y la ética autónoma?",["La moral recibe su ley de fuera, y la ética la extrae de sí misma por deliberación","La moral atañe al individuo aislado, y la ética implica siempre a un colectivo","La moral se transmite por escrito, y la ética se transmite oralmente"],["La heteronomía designa la regla recibida del exterior, y la autonomía la que el sujeto se da a sí mismo.","Es más bien lo contrario: la moral la comparte un grupo, y la reflexión la sostiene el sujeto.","La distinción no depende del soporte, sino del origen de la obligación."]],
  "37": ["¿En qué momento surge la ética?",["Cuando una autoridad reconocida codifica por escrito las reglas de un grupo","Cuando una mediación reflexiva se interpone entre el individuo y la norma recibida","Cuando una sociedad alcanza un consenso unánime sobre el bien y el mal"],["La codificación produce una deontología o un derecho, no el proceder reflexivo que es la ética.","Nace cuando el individuo deja de seguir la regla sin discutirla y pone a prueba la moral vigente.","Un consenso admitido sin examen corresponde todavía a la moral."]],
  "38": ["¿Cómo se distinguen la moral y la ética en su relación con el tiempo?",["La moral se transforma sin cesar, y la ética fija principios inmutables","Ambas evolucionan al mismo ritmo y según los mismos mecanismos","La moral se presenta como inmutable, y la ética conduce a una reflexión dinámica"],["La inversión es completa: es la moral la que se presenta como estable y universalmente válida.","Su diferencia radica precisamente en que una se da como establecida y la otra como cuestionadora.","La ética obliga a preguntarse si lo que se tiene por bueno lo es realmente, lo que vuelve su cuestionamiento siempre situado."]],
  "39": ["¿Cómo comenzó la reflexión ética en Occidente?",["Por la constatación de que lo que estaba bien visto en una ciudad estaba mal visto en otra","Por la codificación escrita de las reglas de conducta propias de cada ciudad","Por la formulación de las primeras reglas de la relación entre profesional y enfermo"],["Ese relativismo llevó a ver la moral como una simple convención y a negar los principios universales.","La puesta por escrito de las reglas produce derecho, no el despertar de la reflexión ética.","Esas reglas profesionales corresponden a la deontología médica, posterior a ese despertar."]],
  "40": ["¿En qué consiste la mayéutica empleada frente al relativismo moral?",["Demostrar mediante un razonamiento continuo que ciertas reglas valen en todas partes","Llevar al interlocutor, mediante preguntas, a examinar de forma crítica sus ideas","Recopilar las costumbres de las ciudades para extraer de ellas los puntos comunes"],["El método procede por interrogación y no por demostración impuesta desde fuera.","El cuestionamiento lo lleva a distinguir lo que tiene valor de lo que hay que rechazar por carecer de fundamento.","Esa descripción comparativa es justamente lo que había conducido al relativismo que se trata de superar."]],
  "41": ["¿Qué es la ética clínica?",["El conjunto de las reglas disciplinarias impuestas a una profesión sanitaria","El estudio de las consecuencias jurídicas de las faltas cometidas con ocasión de la asistencia","La aplicación de los valores a la práctica asistencial para orientar la decisión"],["Ese conjunto constituye la deontología, que fija un mínimo exigible más que un proceder de decisión.","Ese es el objeto de la responsabilidad profesional, que interviene después del acto.","Pone los valores a prueba de las situaciones reales para iluminar la elección del profesional."]],
  "42": ["¿Qué principios establece el juramento hipocrático para la relación asistencial?",["Actuar en el interés del paciente, no dañar y respetar la confidencialidad","Informar al paciente, recoger su acuerdo escrito y respetar su negativa","Declarar sus conflictos de interés, publicar sus resultados y formarse sin cesar"],["Esas tres exigencias forman la base ética que ese texto transmite a la práctica asistencial.","Esas exigencias proceden del reconocimiento moderno de la autonomía, muy posterior.","Esos deberes corresponden a la ética de la investigación y a los códigos contemporáneos."]],
  "43": ["¿Por qué se dice que la deontología y el derecho corresponden a una ética mínima?",["Solo atañen a un número muy pequeño de situaciones profesionales","Fijan el mínimo exigible, allí donde la ética busca la excelencia y la virtud","Carecen de toda sanción en caso de incumplimiento constatado"],["Su carácter mínimo depende del nivel de exigencia, no de la extensión de las situaciones cubiertas.","La conducta ética está sometida a una norma más estricta: constituye una ética máxima.","Son al contrario las únicas de esas disciplinas que van acompañadas de sanciones."]],
  "44": ["¿Cómo se influyen mutuamente la ética y la legislación?",["La legislación determina el contenido de la ética, que no es más que su aplicación","Ambas evolucionan cada una por su lado, sin encontrarse nunca","La ética inspira, la legislación encuadra, y la práctica pone a prueba a ambas"],["Eso sería ignorar que el reconocimiento de un valor precede y motiva la regla de derecho.","Al contrario, se influyen en un movimiento de ida y vuelta constante.","El consentimiento informado lo ilustra: respeto, dignidad y autonomía inspiraron la regla que lo vuelve obligatorio."]],
  "45": ["Un profesional juzga bueno informar a un allegado sin el acuerdo del paciente, para calmar su angustia. ¿De qué se trata?",["De una situación ética pero no legal","De una situación legal pero no ética","De un conflicto de valores entre dos profesionales"],["El profesional tiene la acción por justa, mientras que la ley no la protege o incluso la prohíbe.","Ese caso es el inverso: una conducta autorizada por la ley pero tenida por moralmente inaceptable.","El conflicto opone aquí el juicio del profesional a la regla de derecho, no a dos profesionales entre sí."]],
  "46": ["¿Qué permite la objeción de conciencia y con qué límite se topa?",["Rechazar todo acto que el profesional juzgue inoportuno, sin ninguna condición","Abstenerse de un acto legal contrario a sus convicciones, sin abandonar al paciente","Obtener que la ley se deje de lado para todos los profesionales de un centro"],["Se reconoce en casos limitados y nunca equivale al abandono del paciente.","Reconocida en casos limitados, no exime nunca de la continuidad de la asistencia ni del respeto de los derechos del paciente.","Es una posición individual, que no suspende la aplicación de la ley."]],
  "47": ["¿Por qué no puede limitarse la formación en ética al conocimiento de las normas?",["Las normas cambian demasiado a menudo para que sea útil aprenderlas","Las normas jurídicas no se aplican a los profesionales sanitarios","Hacen falta criterios de reflexión para actuar cuando la ley calla o es ambigua"],["El conocimiento de las normas sigue siendo indispensable: solo resulta insuficiente por sí solo.","Se les imponen plenamente; lo que está en cuestión es su insuficiencia en la situación concreta.","Principios bioéticos y códigos deontológicos aportan esas referencias allí donde la regla falta."]],
  "48": ["¿Cómo se define la bioética?",["El estudio de los problemas morales que plantea la investigación biológica y médica","El conjunto de las reglas disciplinarias impuestas a las profesiones sanitarias","El estudio de las consecuencias jurídicas de las nuevas prácticas biomédicas"],["Versa sobre los dilemas nacidos del desarrollo de las ciencias y técnicas aplicadas a lo vivo.","Esa definición corresponde a la deontología, que encuadra el ejercicio profesional.","El análisis jurídico acompaña a la bioética sin confundirse con su proceder moral."]],
  "49": ["¿Con qué perspectiva se concibió la bioética en su origen?",["Una disciplina destinada a encuadrar jurídicamente los ensayos clínicos","Un diálogo entre científicos y humanistas para preservar la humanidad","Una rama de la medicina legal que peritaba las faltas asistenciales"],["El encuadre de los ensayos corresponde a la regulación de la investigación, posterior y más estrecha.","Su visión inicial era ecologista: tender un puente hacia el futuro frente al consumo excesivo de recursos y a la degradación del medio ambiente.","El peritaje de las faltas corresponde a la responsabilidad profesional, no al proyecto bioético."]],
  "50": ["¿Por qué es la bioética una de las ramas más actuales de la ética?",["Es la única rama de la ética dotada de fuerza vinculante","Se limita a las cuestiones nacidas de la práctica clínica cotidiana","La técnica ha franqueado límites tenidos por infranqueables, lo que trastoca la moral"],["Sus dictámenes carecen por regla general de alcance obligatorio.","Es la ética clínica la que tiene ese alcance restringido; la bioética es mucho más amplia.","Las células madre lo ilustran: lo técnicamente posible obliga a reexaminar convenciones tenidas por inalterables."]],
  "51": ["¿Qué significa que la bioética sea civil o laica?",["Su método es independiente de toda religión y de todo sistema político","Excluye del debate a las personas con convicciones religiosas","Solo interviene en los centros del sector público"],["Su argumentación no extrae su validez de ninguna confesión ni de ningún poder.","Es pluralista y reconoce la pluralidad de los valores, incluidos los religiosos.","Su carácter laico califica su método, no su ámbito de aplicación institucional."]],
  "52": ["¿Cuál de estas características no corresponde a la bioética?",["Mediadora: resuelve los conflictos teniendo en cuenta los valores de cada uno","Dogmática: aplica verdades admitidas sin discusión posible","Procedimental: constituye un recorrido para reflexionar y decidir"],["La mediación entre los valores en presencia forma parte efectivamente de sus características.","Es al contrario racional y filosófica, por tanto argumentativa y deliberativa.","No es una simple reflexión teórica, sino un recorrido que conduce a la decisión."]],
  "53": ["¿Qué significa el carácter «de aplicación práctica» de la bioética?",["Solo se interesa por los gestos técnicos de la asistencia","Expone las posiciones en presencia sin concluir nunca","La deliberación tiene en ella por fin la toma de decisión"],["Su objeto abarca todas las interacciones humanas afectadas por las ciencias de la vida.","Quedarse sin conclusión contradiría precisamente su vocación práctica.","No se detiene en el análisis: debe desembocar en una conducta que seguir."]],
  "54": ["¿Cómo se reparte el trabajo en un proceder bioético interdisciplinar?",["Los científicos tratan los hechos, y las ciencias humanas estudian los valores","Los científicos zanjan a la vez los hechos y los valores en juego","Los juristas arbitran los desacuerdos entre científicos y filósofos"],["Esa articulación une el mundo empírico al mundo moral, lo que es propio de la bioética.","Encomendarles los valores equivaldría a suprimir la dimensión interdisciplinar.","El derecho encuadra la práctica, pero no desempeña ese papel de árbitro en la deliberación."]],
  "55": ["¿Qué distingue la ética clínica de la bioética en cuanto a su alcance?",["Una cubre la investigación y la política, y la otra se limita a la asistencia","Una se limita a la práctica asistencial, y la otra cubre ciencia y tecnología","Las dos tienen el mismo alcance y solo difieren en el vocabulario"],["La inversión es completa: es la bioética la que tiene el alcance más amplio.","La bioética abarca la vida, la salud, la biotecnología, la investigación y la política.","Difieren en el alcance, el nivel de análisis, el objetivo y el contexto."]],
  "56": ["¿En qué nivel de análisis se sitúa cada una de las dos disciplinas?",["La ética clínica en el nivel social, y la bioética en el caso particular","Ambas exclusivamente en el nivel de la institución asistencial","La ética clínica en el caso particular, y la bioética también en los niveles colectivos"],["Ese es exactamente el inverso del reparto entre las dos disciplinas.","El nivel institucional no es más que uno de los tres niveles de la bioética.","El caso clínico concreto es la unidad de análisis de una; la otra incluye lo institucional y lo social."]],
  "57": ["¿Cuáles son, para los profesionales sanitarios, los ámbitos más importantes de la bioética?",["La ética clínica y la ética de la investigación","La ética ambiental y la ética animal","La ética de los negocios y la ética de la comunicación"],["Son los dos campos con los que se encuentran directamente, junto al paciente y en los protocolos.","Esos campos corresponden a la bioética en sentido amplio, sin atañer a su práctica.","Esos ámbitos son ajenos a las ciencias de la vida a las que se aplica la bioética."]],
  "58": ["Entre los dilemas que plantea la inteligencia artificial, ¿cuál no se ha identificado?",["Los sesgos de los algoritmos, derivados de los datos con los que se entrenan","La desaparición programada de toda investigación biomédica realizada por humanos","La falta de fiabilidad de las herramientas, cuyos contenidos pueden estar fabricados"],["Esos sesgos agravan las desigualdades y penalizan más a los grupos ya marginados.","Las cuestiones recogidas versan sobre el empleo, los sesgos, la privacidad, la fiabilidad y la propiedad de los contenidos.","El riesgo de información engañosa forma parte de las preocupaciones identificadas."]],
  "59": ["¿Qué exigencias se imponen a los sistemas de inteligencia artificial en la Unión Europea?",["Ser supervisados por otros sistemas automatizados juzgados más eficaces","Ser desarrollados únicamente por centros públicos de investigación","Ser seguros, transparentes, trazables, no discriminatorios y vigilados por personas"],["Eso es precisamente lo que la norma descarta en favor de una supervisión humana.","Ninguna exigencia versa sobre el estatus jurídico del diseñador.","Se exige la supervisión humana en lugar de la automatización, para evitar resultados dañinos."]],
  "60": ["¿Cómo se define el transhumanismo?",["Un movimiento que propugna la superación de los límites físicos y psíquicos del hombre","Una corriente que rechaza toda intervención tecnológica sobre el cuerpo humano","Una doctrina que reserva las técnicas de reparación solo a las personas enfermas"],["Se basa en la idea de que la ciencia y la tecnología pueden conferir capacidades hasta ahora desconocidas.","Esa posición es exactamente la opuesta al proyecto transhumanista.","Limitar la técnica a la reparación equivale a rechazar la superación que reivindica."]],
  "61": ["¿Qué es un cíborg?",["Un dispositivo electrónico que reproduce el funcionamiento de un organismo","Un ser compuesto de materia viva y de dispositivos electrónicos","Un organismo vivo cuyo patrimonio genético se ha modificado"],["Un dispositivo enteramente artificial no comporta ninguna materia viva.","La definición asocia lo vivo y lo artificial en un mismo organismo.","La modificación genética no hace intervenir ningún dispositivo electrónico."]],
  "62": ["¿Qué estudia la neuroética?",["Las bases neurológicas de la conducta moral en el ser humano","La regulación del secreto médico aplicada a los datos cerebrales","El uso del razonamiento ético frente a las cuestiones nacidas de las neurociencias"],["Describir los mecanismos cerebrales del juicio moral es un objeto de investigación, no un proceder normativo.","Es una cuestión de protección de datos, que no agota el campo de la neuroética.","Versa sobre la investigación, las aplicaciones clínicas y no clínicas y la percepción pública de las neurociencias."]],
  "63": ["A propósito de los implantes neuronales, ¿qué distinción destaca la reflexión ética?",["Rehabilitar una capacidad perdida se admite, y mejorarla plantea cuestiones","La implantación se admite siempre que esté técnicamente dominada","La implantación está prohibida, incluso con fines de rehabilitación"],["La mejora plantea dudas sobre los efectos a largo plazo, el acceso y el riesgo de una subclase entre humanos mejorados y los demás.","El dominio técnico no resuelve la cuestión de la finalidad perseguida.","La rehabilitación de capacidades perdidas es precisamente el caso aceptado."]],
  "64": ["¿Cuál es el alcance de los dictámenes que emiten los comités de ética?",["Jurídicamente vinculantes para el conjunto de los centros sanitarios","No vinculantes, salvo en investigación, donde su aprobación condiciona el estudio","Simples opiniones sin ninguna consecuencia, incluso en materia de investigación"],["Sus conclusiones no tienen fuerza obligatoria, salvo en el caso de los comités de investigación.","No disponen de ningún poder normativo directo, con esa única excepción.","La aprobación de un comité de investigación es al contrario una condición esencial para el estudio."]],
  "65": ["¿Qué caracteriza a un comité de ética como instancia?",["Una jurisdicción especializada que zanja los litigios entre pacientes y profesionales","Un órgano de control que sanciona los incumplimientos deontológicos constatados","Un espacio de deliberación interdisciplinar que ilumina la toma de decisión"],["La resolución de los litigios corresponde a los tribunales, no a los comités de ética.","La sanción disciplinaria corresponde al colegio profesional.","La pluralidad de miradas permite analizar el dilema desde múltiples ángulos sin confiscar la decisión."]],
  "66": ["¿Qué particularidad distingue al comité internacional de bioética de las Naciones Unidas?",["Es el único organismo universal de reflexión sobre la bioética","Es el único comité cuyos dictámenes se imponen a los Estados que son miembros","Es el único comité compuesto exclusivamente por investigadores científicos"],["Sus miembros siguen los avances de la investigación en ciencias de la vida y velan por el respeto de los principios universales.","Como las demás instancias de ese tipo, formula dictámenes carentes de fuerza obligatoria.","Su composición es pluridisciplinar, a imagen del proceder bioético."]],
  "67": ["¿Cuál de estas misiones no corresponde al comité nacional de bioética español?",["Fijar los principios de los códigos de buenas prácticas de investigación científica","Autorizar la comercialización de los dispositivos médicos innovadores","Representar al país en los foros internacionales dedicados a la bioética"],["La definición de esos principios generales figura efectivamente entre sus misiones.","Esa autorización corresponde a las autoridades sanitarias competentes, no a una instancia consultiva.","Esa representación forma parte de sus atribuciones."]],
  "68": ["¿Cuál es el papel del comité consultivo nacional de ética en Francia?",["Autorizar o rechazar los protocolos de investigación en seres humanos","Juzgar los incumplimientos éticos cometidos por los profesionales sanitarios","Iluminar a los decisores y al debate público, a partir de las consultas que recibe"],["Esa autorización corresponde a los comités de protección de las personas.","Su carácter estrictamente consultivo excluye toda función jurisdiccional.","Organismo estrictamente consultivo, reflexiona sobre las cuestiones sociales nacidas de la evolución de las ciencias de la vida."]],
  "69": ["¿Qué garantiza la ley en la composición de esa instancia consultiva nacional?",["Una pluridisciplinariedad y un pluralismo que cruzan las miradas sobre cada cuestión","Una mayoría de profesionales sanitarios actualmente en ejercicio","Una representación igual de cada una de las confesiones religiosas"],["Es la diversidad de puntos de vista la que fundamenta la calidad del asesoramiento aportado.","No se prevé ningún predominio de una profesión; lo que se busca es la pluralidad.","El proceder es laico y se basa en un método independiente de toda religión."]],
  "70": ["¿En qué principios se basaba la ética médica tradicional?",["Respetar la autonomía y repartir equitativamente los recursos","No dañar y hacer el bien","Informar al paciente y recoger su consentimiento escrito"],["La autonomía es el más moderno de los principios y la justicia distributiva es posterior a esa tradición.","Exigidas primero a los médicos, esas dos reglas se han extendido a todos los profesionales de las ciencias médicas.","Esas obligaciones proceden del reconocimiento de la autonomía, ajeno a esa tradición."]],
  "71": ["¿Qué función cumplía el juramento hipocrático?",["Una regla impuesta a los médicos por la autoridad pública de su ciudad","Un contrato que vinculaba individualmente al médico con cada uno de sus pacientes","La más antigua autorregulación de la práctica en el seno mismo de la profesión"],["Su originalidad radica precisamente en que la profesión se daba a sí misma su regla.","Se trataba de un compromiso profesional general, no de un acuerdo cerrado paciente por paciente.","Buscaba evitar o atenuar las consecuencias indeseables de la práctica, y se ha desarrollado en los códigos actuales."]],
  "72": ["¿Qué provocó el nacimiento de la bioética moderna?",["Acontecimientos que mostraron que los principios fundamentales no se respetaban","La publicación de nuevos códigos de deontología por los colegios profesionales","La prolongación de la esperanza de vida en los países más desarrollados"],["Experimentos con presos y estudios realizados sin consentimiento alarmaron a científicos y humanistas.","Esos códigos acompañaron el movimiento sin ser su causa desencadenante.","Ese fenómeno presiona el reparto de los recursos, pero no está en el origen de la disciplina."]],
  "73": ["En el estudio sobre la sífilis realizado en Tuskegee, ¿qué incumplimientos se cometieron?",["Consentimiento recogido, pero sin información sobre la duración real del estudio","Ausencia de consentimiento, diagnósticos falsos y privación del tratamiento eficaz","Tratamiento correctamente administrado, pero resultados nunca publicados después"],["La ausencia total de consentimiento informado es precisamente lo que está en cuestión.","El reclutamiento se dirigió además a hombres muy pobres y poco instruidos, proclives a someterse a las figuras de autoridad.","La falta de tratamiento, a pesar de existir un remedio eficaz, constituye el núcleo del escándalo."]],
  "74": ["¿Cómo supieron los participantes de ese estudio que eran sus sujetos?",["Por una información individual que les entregaron los investigadores al final","Por una resolución judicial que los indemnizó antes del final del estudio","Por los medios de comunicación, décadas después del inicio del estudio"],["No se les facilitó ninguna información por parte del equipo de investigación.","La revelación pública precedió a todo reconocimiento del perjuicio.","No se les informó ni en el momento de la inclusión ni durante el desarrollo del estudio."]],
  "75": ["¿Qué caracteriza al estudio realizado en una escuela que acogía niños con discapacidad?",["Los niños fueron inoculados deliberadamente con un virus de la hepatitis","Los niños recibieron una vacuna experimental sin conocimiento de sus padres","Los niños fueron privados de los cuidados habituales que les correspondían"],["Se observaba después el efecto de un tratamiento; una protesta general obligó a detener el estudio.","No se trataba de una vacunación, sino de una inoculación deliberada del agente infeccioso.","El estudio versaba sobre una infección provocada, no sobre la privación de cuidados habituales."]],
  "76": ["¿Qué principios estableció el informe fundador de la ética de la investigación?",["El respeto de las personas, la beneficencia y la justicia","La autonomía, la no maleficencia, la beneficencia y la justicia","La beneficencia, la no maleficencia y el secreto profesional"],["El respeto de las personas engloba la autonomía y la protección de quienes no pueden ejercerla.","Esos cuatro principios forman el principialismo, formulado después a partir de ese informe.","El secreto es una obligación deontológica, no uno de los principios fundadores establecidos."]],
  "77": ["¿Qué es el principialismo?",["Una teoría completa que da por adelantado la solución de cada dilema","Un marco de cuatro principios que sirve para analizar los problemas morales de la asistencia","Un método que aplica la norma jurídica más protectora del paciente"],["Esos cuatro principios no constituyen una teoría, sino un marco metodológico.","Aporta los ingredientes iniciales del dilema ético y facilita su resolución concreta.","El enfoque es ético y deliberativo: no se reduce a la aplicación de una norma."]],
  "78": ["¿Qué significa que los cuatro principios sean «prima facie»?",["Están ordenados por importancia decreciente y se aplican en ese orden","Solo son recomendaciones carentes de carácter obligatorio","Obligan mientras no entren en conflicto, caso en el que se privilegia uno de ellos"],["Precisamente, no son objeto de ninguna jerarquización a priori.","Son vinculantes mientras no surja ningún conflicto entre ellos.","No se establece de antemano ninguna jerarquía ni prioridad entre ellos."]],
  "79": ["¿Cómo debe realizarse el arbitraje entre dos principios en conflicto?",["En la situación concreta, comparando los escenarios posibles","Aplicando una jerarquía de los principios fijada de una vez por todas","Remitiéndose al marco jerárquico del centro asistencial"],["La solución mejor o menos mala debe después asumirse y legitimarse con argumentos.","No se establece abstractamente ninguna jerarquía a priori entre los principios.","El arbitraje procede de una deliberación argumentada, no de una autoridad administrativa."]],
  "80": ["¿Cómo se define el principio de autonomía?",["La libertad del profesional de elegir la técnica que juzga más adecuada","La autodeterminación: el paciente decide libremente tras un intercambio de información","El derecho del paciente de exigir todo tratamiento que estime útil para él"],["La autonomía en cuestión es la del paciente, no la libertad terapéutica del profesional.","Su núcleo duro es un principio de autorización y de participación: se requiere su permiso para toda acción sobre su persona.","El principio fundamenta una autorización y una participación, no un derecho a exigir cualquier acto."]],
  "81": ["¿Qué capacidades supone el ejercicio de la autonomía?",["Una formación previa del paciente en las nociones médicas en juego","La mayoría de edad civil y la plena capacidad jurídica en todos los casos","Capacidades mentales como la comprensión y la intencionalidad"],["La información necesaria y suficiente la facilita el profesional; no se exige ninguna formación.","El menor maduro o la persona con medidas de apoyo participan en la medida de sus capacidades.","Sin comprensión de la información ni intención propia, la decisión no puede tenerse por autónoma."]],
  "82": ["¿Qué implica el respeto de la autonomía para el profesional?",["Informar suficientemente y verificar la comprensión y la libertad de la elección","Hacer firmar un documento antes de la intervención, sin otra formalidad","Dejar al paciente decidir solo, sin información que pueda influirle"],["Esa es la exigencia del consentimiento libre e informado, esencial tanto en la asistencia corriente como en investigación.","La firma no vale nada si no se verifican la comprensión y la libertad de la decisión.","La información es la condición misma de la autonomía, no una influencia que haya que evitar."]],
  "83": ["¿Cuál es el corolario del derecho a aceptar un tratamiento?",["El derecho a exigir en su lugar un tratamiento alternativo de su elección","El derecho a rechazarlo, incluso vital, salvo excepciones previstas por la ley","Ninguno: una vez informado, el paciente debe aceptar el tratamiento indicado"],["El corolario de la aceptación es el rechazo, no un derecho a exigir otra terapia.","Enfermedades contagiosas y hospitalización no voluntaria figuran entre las excepciones codificadas.","El rechazo informado es precisamente la contrapartida del consentimiento."]],
  "84": ["¿Qué es el paternalismo en salud?",["El profesional se abstiene de todo juicio para no influir en el paciente","La familia se sustituye al paciente para fijar la conducta que hay que seguir","El profesional decide el bien del paciente, con benevolencia pero con autoridad"],["Ese retraimiento es lo contrario del paternalismo, que se caracteriza por una decisión tomada en lugar del paciente.","El paternalismo designa la sustitución por el profesional, no por los allegados.","El principio de autonomía se le opone al hacer primar los valores y las preferencias del paciente, en virtud de su dignidad."]],
  "85": ["¿Qué lugar ocupa la autonomía entre los principios de la bioética?",["Es el más moderno de ellos","Es el más antiguo, ya presente en la medicina hipocrática","Es el que suscita menos empatía y menos incita a actuar"],["Introduce los valores del paciente en la deliberación y lo convierte en un actor principal de la asistencia.","Son la no maleficencia y la beneficencia las que se remontan a esa tradición.","Esa característica es la del principio de justicia."]],
  "86": ["¿Qué impone el principio de no maleficencia?",["Garantizar la ausencia de todo efecto adverso, incluso muy improbable","Evitar todo perjuicio inútil, desproporcionado o injustificado al paciente","Renunciar a todo acto que comporte una parte de riesgo para el paciente"],["No incluye los perjuicios no intencionales, como un efecto raro de un medicamento bien empleado.","Retoma la exigencia hipocrática de no dañar e impone que los beneficios prevalezcan sobre los riesgos.","Exige un balance favorable, no la abstención ante todo riesgo."]],
  "87": ["¿Cuál de estos perjuicios no entra en el ámbito de la no maleficencia?",["Un perjuicio causado por negligencia o por falta de conocimientos","Un perjuicio causado al poner otros valores por delante del paciente","Un efecto raro surgido con un medicamento indicado y correctamente utilizado"],["La negligencia y la incompetencia figuran entre las formas de causar un perjuicio.","Hacer primar consideraciones económicas o de reputación es un atentado directo contra el principio.","Los perjuicios no intencionales de ese tipo quedan expresamente excluidos del ámbito del principio."]],
  "88": ["¿Cómo zanjar entre «no dañar» y «aportar un beneficio» de riesgo incierto?",["Dar prioridad a la prevención del perjuicio","Dar prioridad al beneficio, al ser el riesgo por naturaleza incierto","Remitirse sistemáticamente a la elección que exprese el paciente"],["La prudencia se impone tanto más cuanto que el beneficio es dudoso o el perjuicio grave e irreversible.","La incertidumbre del beneficio es al contrario un motivo adicional de prudencia.","La elección del paciente corresponde a la autonomía y no resuelve por sí sola ese arbitraje."]],
  "89": ["¿A qué principio atenta la obstinación irrazonable?",["A la justicia, por la movilización excesiva de los recursos colectivos","A la no maleficencia, de la que constituye un incumplimiento frecuente","A la autonomía, por falta de recogida del consentimiento del paciente"],["El consumo de recursos es una consecuencia accesoria; el atentado primero recae sobre la ausencia de perjuicio.","El paciente incurable sufre en ella tratamientos que solo agravan dolorosamente el deterioro de su salud.","La obstinación puede producirse incluso con el acuerdo del paciente: lo que está en cuestión es el daño causado."]],
  "90": ["¿Cuál de estas conductas ilustra una acción no maleficente?",["Mantener un tratamiento ineficaz para no decepcionar al paciente","Aplicar una técnica contraindicada que el paciente reclama","Interrumpir una medicación reconocida como peligrosa para el paciente"],["Mantener un tratamiento sin beneficio expone al riesgo sin ninguna contrapartida.","Una técnica contraindicada nunca se vuelve aceptable, cualquiera que sea el contexto.","El profesional descarta un riesgo que no se compensaría con ningún beneficio demostrado."]],
  "91": ["¿En qué supera la beneficencia a la no maleficencia?",["Exige una acción positiva, y no la sola abstención de dañar","Impone no exponer al paciente a ningún riesgo, ni siquiera mínimo","Obliga a seguir en toda circunstancia la voluntad del paciente"],["El profesional debe promover activamente el bienestar, la salud y los intereses del paciente.","Esa exigencia absoluta correspondería a la no maleficencia, y aun así de forma excesiva.","El respeto de la voluntad procede de la autonomía, a veces en conflicto con la beneficencia."]],
  "92": ["¿Qué exige el principio de utilidad, componente de la beneficencia?",["Adoptar sistemáticamente la opción menos costosa para el centro","Comparar las alternativas y adoptar la mejor relación beneficio/riesgo","Adoptar la opción más reciente en el plano tecnológico disponible"],["El criterio es el beneficio para el paciente, no el ahorro conseguido.","No basta con querer hacer el bien: hay además que comparar las líneas de conducta posibles.","La novedad no garantiza una mejor relación entre beneficio y riesgo."]],
  "93": ["¿En qué condiciones se convierte la beneficencia en una obligación moral?",["Desde que el paciente formula una petición, cualquiera que sea su carga","Solo cuando el centro dispone de recursos excedentarios","Riesgo real, acción necesaria y eficaz, y beneficio superior al coste"],["El deber es modulable y está limitado por la proporcionalidad entre el coste y el beneficio.","El estado de los recursos modula el esfuerzo exigible sin condicionar la existencia de la obligación.","Esas tres condiciones reunidas transforman la posibilidad de actuar en deber de actuar."]],
  "94": ["¿Qué supone, para el profesional, dotarse de los medios para ser beneficente?",["Formarse de forma continua y apoyarse en la investigación que mejora la asistencia","Aceptar todas las peticiones de los pacientes para no dañarlos nunca","Delegar las decisiones complejas en un comité de ética competente"],["Ese es el vínculo directo con la noción de fisioterapia basada en la evidencia.","Acceder a toda petición puede al contrario conducir a actos sin beneficio demostrado.","El comité ilumina la decisión sin eximir al profesional de su deber de competencia."]],
  "95": ["¿Qué opone la no maleficencia y la beneficencia en cuanto a su nivel de exigencia?",["La primera se modula según los medios, y la segunda es absoluta","La primera es absoluta, y la segunda se modula según la carga y los recursos","Ambas se modulan igualmente según el contexto del centro"],["La inversión es completa: aplicar una técnica contraindicada sigue siendo siempre inaceptable.","No puede exigirse un esfuerzo ilimitado: el límite depende de la proporcionalidad entre coste y beneficio.","Solo la beneficencia se modula; la prohibición de dañar no admite ninguna adaptación."]],
  "96": ["¿De dónde nacen numerosos dilemas que oponen beneficencia y autonomía?",["El profesional se niega a facilitar la información debida al paciente","El centro limita el número de actos cubiertos por paciente","El paciente elige una opción que el profesional no juzga la más beneficiosa"],["La retención de información es un atentado directo contra la autonomía, no un conflicto entre dos principios.","Esa restricción pone en juego la justicia distributiva más que la beneficencia.","Ese desacuerdo constituye el terreno clásico del paternalismo."]],
  "97": ["¿Qué impone el principio de justicia en materia asistencial?",["Un acceso igual a los recursos, sin privilegio ni discriminación","Más recursos a los pacientes que más financian el sistema","Un trato estrictamente idéntico para todos, al margen de las necesidades"],["Se trata de una justicia distributiva, fundada en criterios racionales y no en la arbitrariedad.","Vincular el acceso a la contribución económica constituye precisamente una discriminación prohibida.","La igualdad buscada versa sobre el acceso y la consideración, y tiene en cuenta las necesidades de cada uno."]],
  "98": ["¿Por qué viola el principio de justicia prescribir una prueba no indicada?",["Expone al paciente a un riesgo desproporcionado para él mismo","Moviliza inútilmente recursos y retrasa el acceso de otros pacientes","Contraviene el consentimiento informado que ha dado el paciente"],["Ese razonamiento corresponde a la no maleficencia y no al reparto de los recursos.","El buen uso de los recursos públicos forma parte integrante de la exigencia de justicia.","El consentimiento puede haberse recogido sin que el atentado contra la justicia desaparezca."]],
  "99": ["¿Cuál de estas referencias no figura entre las reglas que orientan el principio de justicia?",["La regla de igualdad de oportunidades y el rechazo de la discriminación","La transparencia de las decisiones y el rechazo de los conflictos de interés","La prioridad a los pacientes cuyo pronóstico es más favorable"],["Esas dos referencias figuran explícitamente entre las reglas enunciadas.","La transparencia y la ausencia de conflictos de interés forman parte de las referencias establecidas.","Ese criterio de selección no figura entre las referencias, que excluyen toda discriminación."]],
  "100": ["¿A qué se llama microasignación?",["La decisión de atribuir un recurso limitado a un paciente y no a otro","El reparto del presupuesto de la salud entre las distintas regiones","La atribución de los créditos de investigación entre los equipos candidatos"],["Camas de cuidados intensivos u órganos disponibles vuelven difícil la igual consideración debida a cada uno.","Ese reparto de conjunto corresponde a las decisiones de política sanitaria, por tanto a la macroasignación.","Esa financiación no atañe a la distribución de la asistencia entre los pacientes."]],
  "101": ["¿Por qué suscita la justicia menos empatía y menos incita a actuar?",["Solo atañe a los responsables políticos y no a los profesionales","Se opone a menudo a la autonomía del paciente o al bien individual buscado","Es el más reciente de los cuatro principios de la bioética"],["Convoca a los profesionales sanitarios tanto como a la política sanitaria.","Tener en cuenta el coste para el grupo conduce a veces a limitar lo que sería deseable para un paciente.","Es la autonomía el más moderno de los principios."]],
  "102": ["En el cuadro que relaciona valores, principios y asistencia, ¿a qué corresponde la libertad?",["A la beneficencia y a la eficacia de la terapia aplicada","A la justicia, a la equidad y a la distribución de los recursos","A la autonomía, al modelo deliberativo y al consentimiento informado"],["La eficacia terapéutica responde a los valores de cuidado, humanización y calidad de vida.","La equidad y la correcta distribución responden a los valores de solidaridad e igualdad.","La libertad del paciente se traduce en su participación en la decisión y en la autorización que concede."]],
  "103": ["¿Qué es humanizar la asistencia sanitaria?",["Personalizar la asistencia centrándola en la persona que hay detrás de la enfermedad","Mostrar cordialidad y amabilidad con cada paciente atendido","Reducir los tiempos de espera y agilizar el recorrido por el centro"],["Eso supone abandonar la tendencia a tratar al paciente como una enfermedad.","La humanización va mucho más allá de la cordialidad: cambia la naturaleza misma de la relación.","La organización de los flujos no afecta a la consideración de la persona enferma."]],
  "104": ["¿A quién coloca la humanización de la asistencia en el centro de la organización?",["Solo al paciente, estando los demás actores al servicio de su atención","Al paciente, pero también al personal asistencial y a los acompañantes","Al equipo asistencial, cuyo bienestar condiciona la calidad de la asistencia"],["Reducir la humanización únicamente al paciente olvida al profesional y al acompañante.","Se trata de cuidar al paciente y al profesional, pues los allegados sufren a veces más que el enfermo.","El bienestar de los profesionales es necesario, pero no basta para definir el proceder."]],
  "105": ["¿Cuál es la herramienta fundamental de la humanización de la asistencia?",["La medición regular de la satisfacción mediante cuestionarios","La formación técnica continua del conjunto de los equipos asistenciales","La escucha activa de los profesionales a pacientes, familias y colegas"],["La recogida de indicadores no sustituye la escucha directa de las personas implicadas.","La competencia técnica se ha privilegiado precisamente en detrimento de la competencia humana.","Las asociaciones de pacientes, las familias convertidas en cuidadoras y los profesionales son los actores clave a los que hay que escuchar."]],
  "106": ["¿Cómo se describe la transformación de la persona en paciente?",["La vida se interrumpe, el decorado cambia y la identidad se pierde en unas horas","El paciente se adapta progresivamente a su nuevo papel a lo largo del ingreso","El paciente conserva sus referencias gracias a la presencia de sus allegados"],["El enfermo se convierte en «el paciente de la habitación 304», sin tiempo para adaptarse emocionalmente a ese papel.","La transformación se produce al contrario en unas horas, sin plazo de adaptación.","El cambio de decorado y la pérdida de identidad se producen a pesar del entorno."]],
  "107": ["¿Cuál de estas causas de deshumanización no se ha identificado?",["La presión institucional y el agotamiento profesional de los equipos","La disminución del número de actos técnicos que realizan los profesionales","La fragmentación del cuerpo y la desatención del sufrimiento del enfermo"],["El burnout figura entre las causas directamente identificadas.","Las causas señaladas son la medicalización excesiva, el agotamiento, la fragmentación y las jerarquías verticales.","Esa fragmentación se cita explícitamente entre las causas."]],
  "108": ["¿Qué consecuencias conlleva la deshumanización en fisioterapia?",["Aumento del número de sesiones necesarias y de los costes de la atención","Multiplicación de los conflictos entre los distintos profesionales del equipo","Pérdida del vínculo terapéutico, dolor más crónico y menor adherencia"],["El sobrecoste es una consecuencia indirecta y no se ha recogido entre los efectos descritos.","Las jerarquías verticales son una causa de deshumanización, no una de sus consecuencias.","El deterioro de la relación entre el fisioterapeuta y su paciente agrava la cronificación del dolor."]],
  "109": ["¿Qué papel desempeña la tecnología en la deshumanización?",["Mal empleada y sin intención humanizadora, se convierte en un obstáculo para una asistencia humana","Humaniza mecánicamente la asistencia al liberar tiempo para la relación","No tiene efecto sobre la calidad relacional, que depende únicamente del profesional"],["La asistencia se ha vuelto cada vez más técnica, en detrimento de las relaciones interpersonales.","El tiempo liberado no se ha reinvertido en la relación, y la asistencia se ha mecanizado al contrario.","El lugar que ocupa la técnica condiciona directamente la calidad de la relación."]],
  "110": ["¿Cuál de estos menoscabos no figura entre las formas en que se compromete la dignidad?",["La dependencia de otros para realizar las actividades más elementales","La dificultad de obtener una cita en un plazo razonable","La reducción de la persona a un diagnóstico o a un número de habitación"],["Esa dependencia figura entre los menoscabos directamente descritos.","Los menoscabos recogidos son la pérdida de intimidad, la dependencia, la despersonalización y la pérdida de poder de decisión.","La despersonalización es uno de los menoscabos centrales de la dignidad."]],
  "111": ["¿Qué beneficios han demostrado las estrategias de humanización?",["Una reducción del número de profesionales necesarios por servicio","Un aumento del número de pacientes tratados cada día","Menos ansiedad y dolor, recuperación acelerada y personal más fidelizado"],["No se asocia ninguna disminución de plantilla a esas estrategias.","El objetivo perseguido no es el rendimiento, sino la calidad de la experiencia y de los resultados.","El consumo de medicamentos también disminuye, en un sector donde el absentismo es el más elevado."]],
  "112": ["¿Qué destaca la ética del «care» como eje de la moralidad?",["La relación, la interdependencia y la responsabilidad emocional","La aplicación rigurosa de principios universales a cada situación","La maximización del beneficio colectivo obtenido con los recursos empleados"],["Cuidar es tomar las preocupaciones y las necesidades del otro como base de la acción.","Ese enfoque por principios es el del principialismo, no el de la ética del care.","Ese razonamiento utilitarista es ajeno a la lógica relacional del care."]],
  "113": ["¿Qué distinción introduce la ética del care?",["Tratar corresponde al profesional, y cuidar corresponde exclusivamente a la familia","Tratar corresponde a la tradición terapéutica, y cuidar alivia el sufrimiento","Tratar atañe al cuerpo, y cuidar atañe únicamente al psiquismo"],["El acompañamiento forma parte integrante del papel del profesional.","No se trata solo de tratar, sino también de acompañar y de sostener.","La distinción no coincide con el reparto entre lo físico y lo psíquico."]],
  "114": ["¿Qué fase de la atención corresponde a la toma de conciencia de la necesidad?",["Taking care of: asumir la responsabilidad de los cuidados que hay que organizar","Care giving: realizar concretamente el trabajo de cuidado junto al paciente","Caring about: preocuparse por el otro y percibir la necesidad de cuidar"],["Esa fase sigue a la toma de conciencia y corresponde al principio de responsabilidad.","Esa fase es la de la realización, a la que responde el principio de competencia.","Es la primera de las cuatro fases, de la que se deriva el principio ético de atención."]],
  "115": ["¿A qué fase corresponde la reacción de la persona atendida?",["Care receiving, a la que responde el principio de capacidad de respuesta","Care giving, a la que responde el principio de competencia","Caring about, a la que responde el principio de atención"],["Esa reacción permite evaluar si la atención ha sido adecuada y ajustar el tratamiento.","Esa fase designa el trabajo concreto de cuidado, no la respuesta del paciente.","Esa fase es la de la toma de conciencia inicial de la necesidad."]],
  "116": ["¿Qué abarca el «caring with» en la aplicación del modelo en fisioterapia?",["Aplicar las técnicas manuales con seguridad y profesionalidad","Promover la equidad de acceso, trabajar en equipo y volver al paciente corresponsable","Recoger la vivencia del paciente para ajustar las cargas de ejercicio"],["Esa exigencia corresponde al care giving y al principio de competencia.","Esa dimensión remite a los valores de solidaridad y de justicia.","Esa respuesta corresponde al care receiving y a la capacidad de respuesta."]],
  "117": ["¿Cómo se concibe la vulnerabilidad en la relación clínica?",["Como un estado propio del paciente, que el profesional debe compensar","Como una debilidad pasajera ligada únicamente al momento del ingreso","Como una condición humana compartida, que afecta también al terapeuta"],["Limitar la vulnerabilidad al paciente desconoce la del profesional.","Es una condición humana duradera, exacerbada por el sufrimiento y la pérdida de autonomía.","Inseguridad, impotencia y agotamiento emocional vuelven vulnerable al profesional a su vez."]],
  "118": ["¿Cómo se define la compasión en la relación asistencial?",["Una empatía activa acompañada del deseo de aliviar el sufrimiento","Un sentimiento de lástima experimentado ante la angustia de la persona enferma","Un distanciamiento emocional que protege al profesional del agotamiento"],["Exige presencia, autorregulación y apertura emocional, y no se confunde con la lástima.","La compasión se distingue precisamente de la lástima, que coloca al otro en posición de inferioridad.","La compasión supone al contrario una apertura emocional controlada."]],
  "119": ["¿Qué implica el respeto relacional más allá del consentimiento formal?",["Recoger sistemáticamente el acuerdo escrito antes de cada acto realizado","Reconocer la dignidad, las necesidades, los límites y las opiniones sin juzgar","Abstenerse de todo intercambio personal para preservar la neutralidad"],["Ese es precisamente el consentimiento formal que el respeto relacional supera.","El respeto en la asistencia supera la simple formalidad de la autorización firmada.","La neutralidad distante priva a la relación del reconocimiento que exige."]],
  "120": ["¿Por qué es crucial el primer contacto con el paciente?",["Permite recoger lo esencial de los datos administrativos de la historia","Permite anunciar de entrada el pronóstico para evitar falsas expectativas","Permite crear la relación personal en la que se apoyan el diagnóstico y la asistencia"],["La recogida administrativa no tiene ningún alcance sobre la calidad del vínculo terapéutico.","Las expectativas se trabajan a lo largo de la relación, no mediante un anuncio inicial.","La comodidad que siente el paciente hacia el profesional condiciona el establecimiento de un vínculo de confianza."]],
  "121": ["¿Cuáles son las tres dimensiones de la relación terapéutica?",["Los objetivos, las actividades para alcanzarlos y el vínculo entre las dos personas","El diagnóstico, el tratamiento aplicado y la evaluación final de los resultados","La información facilitada, el consentimiento recogido y el secreto garantizado"],["Objetivos negociados, tareas acordadas y vínculo afectivo recíproco forman la relación.","Esa secuencia describe el proceder clínico, no la relación terapéutica.","Esas tres obligaciones son jurídicas y no constituyen las dimensiones del vínculo."]],
  "122": ["¿En qué se apoya el vínculo entre el fisioterapeuta y su paciente?",["Una relación estrictamente funcional limitada a la ejecución de los cuidados","Un vínculo afectivo mutuo fundado en el respeto, la confianza y la aceptación","Una autoridad del profesional que el paciente acepta y a la que se ajusta"],["La asistencia humanizada supone abandonar las relaciones funcionales en favor de relaciones personales.","Es un elemento fundamental del trabajo terapéutico, junto con los objetivos y las tareas.","La relación de autoridad vertical figura entre las causas de deshumanización."]],
  "123": ["¿Cuáles son las expectativas más frecuentes de los pacientes?",["La rapidez de la atención y el control del coste del tratamiento","El acceso a las técnicas más recientes y a los mejores equipos","La curación, la comprensión, la información y los cuidados"],["Esas preocupaciones existen, pero no figuran entre las expectativas recogidas.","La demanda tecnológica no está en el primer plano de las expectativas expresadas.","Esas expectativas son a veces irrealistas, lo que suscita temores que el profesional deberá calmar."]],
  "124": ["¿Cómo se manifiesta el miedo a ser juzgado o incomprendido en un paciente?",["Puede ocultar información o adoptar conductas defensivas","Se vuelve exigente y desconfiado con el equipo que lo atiende","Se bloquea, se vuelve irritable o se instala en la negación de su enfermedad"],["Esa ocultación perjudica directamente la calidad de la evaluación y de la atención.","Esa conducta refleja más bien el temor de que se le oculte información.","Esas reacciones se relacionan con el temor de que el estado sea incurable."]],
  "125": ["¿Qué riesgo comportan las conductas de dependencia en el paciente?",["Rechaza los cuidados propuestos e interrumpe prematuramente el tratamiento","Su autonomía queda anulada y aparecen conductas regresivas","Cuestiona sistemáticamente las decisiones que toma el profesional"],["El rechazo corresponde más bien a la negación o a la desconfianza que a la dependencia.","La necesidad de ser atendido se satisface a costa de la capacidad de decisión del paciente.","El cuestionamiento refleja la desconfianza, no la dependencia."]],
  "126": ["¿Qué designa la comunicación paraverbal?",["Los gestos, los movimientos y el contacto visual entre los interlocutores","Las palabras empleadas, que siempre requieren una interpretación","La manera en que se dicen las cosas: tono, velocidad, timbre y silencios"],["Esos elementos corresponden a la comunicación no verbal.","Las palabras constituyen la comunicación verbal propiamente dicha.","Se distingue tanto de las palabras mismas como de los gestos que las acompañan."]],
  "127": ["¿Cuál es la particularidad de la comunicación humana?",["Es multimodal y simultánea, y los tres registros operan al mismo tiempo","Es secuencial, y cada registro interviene a su turno en el intercambio","Es esencialmente verbal, y los demás registros son solo accesorios"],["Verbal, paraverbal y no verbal se producen conjuntamente y se influyen mutuamente.","Los medios utilizados se producen al mismo tiempo y no sucesivamente.","Lo que se hace modifica la interpretación de lo que se dice: los demás registros son determinantes."]],
  "128": ["¿Qué caracteriza al modelo paternalista de relación terapéutica?",["El profesional facilita toda la información y ejecuta la elección del paciente","El profesional elige lo que juzga mejor e informa de forma selectiva","El profesional clarifica los valores del paciente sin juzgarlos ni discutirlos"],["Ese es el modelo informativo, en el que el profesional actúa como técnico experto.","Su papel es el de un tutor; el modelo supone un criterio objetivo de lo mejor que el paciente asume.","Ese es el modelo interpretativo, en el que el profesional es consultor y consejero."]],
  "129": ["¿En qué situación conserva interés el modelo paternalista?",["En las atenciones prolongadas, en las que ahorra tiempo de intercambio","En los casos en que el paciente tiene un buen conocimiento de su patología","En las situaciones que ponen la vida en peligro, en las que permite actuar rápido"],["La duración de la atención no justifica decidir en lugar del paciente.","Un paciente informado es precisamente aquel para quien ese modelo conviene menos.","Fuera de esas situaciones, reduce la autonomía del paciente."]],
  "130": ["¿Qué caracteriza al modelo informativo?",["El paciente conoce sus valores pero no los hechos; elige, y el clínico ejecuta","El paciente ignora sus valores, que el profesional debe ayudarle a clarificar","Los valores del paciente se discuten y se revisan con el profesional"],["El papel del profesional es el de un técnico experto, proveedor de información, lo que aumenta la autonomía.","Esa situación corresponde al modelo interpretativo.","Esa discusión moral caracteriza al modelo deliberativo."]],
  "131": ["¿Cuál es el papel del profesional en el modelo interpretativo?",["Tutor: determina lo que es mejor y conduce al paciente a consentirlo","Consultor y consejero: clarifica los valores del paciente sin juzgarlos","Docente y guía: acompaña al paciente en un debate moral"],["Ese papel de tutor define el modelo paternalista.","Propone después las opciones que más respetan esos valores, y el paciente elige.","Ese papel corresponde al modelo deliberativo."]],
  "132": ["¿Qué distingue el modelo deliberativo de los demás modelos?",["En él el profesional ejecuta sin discusión la elección que expresa el paciente","En él el profesional interpreta los valores del paciente sin discutirlos nunca","En él los valores del paciente quedan abiertos a la discusión y a la revisión"],["Esa ejecución sin debate caracteriza al modelo informativo.","La interpretación sin discusión define el modelo interpretativo.","La autonomía se concibe en él como un desarrollo moral de uno mismo, y el profesional actúa como docente y guía."]],
  "133": ["¿Por qué se considera ideal el modelo deliberativo en numerosos contextos?",["Favorece a la vez la autonomía del paciente y la calidad de las intervenciones","Es el más rápido de aplicar en la práctica cotidiana","Exime al profesional de tener que justificar sus recomendaciones"],["Exige en contrapartida tiempo y formación, lo que a veces limita su uso.","Requiere al contrario tiempo, lo que constituye su principal límite.","Supone al contrario un debate moral argumentado con el paciente."]],
  "134": ["¿Basta respetar la ley y el código deontológico para ejercer de manera ética?",["No: eso no implica que la práctica sea conforme a la ética","Sí: el código y la ley definen enteramente el ejercicio ético","Sí, siempre que el profesional los conozca perfectamente"],["El ejercicio ético supone integrar la reflexión en las propias actitudes, el lenguaje y las interacciones.","La legislación fija los mínimos; la ética aspira a los máximos deseables.","El conocimiento de los textos no garantiza el compromiso ético del profesional."]],
  "135": ["¿Cuál de estos principios europeos completa los principios de la bioética?",["La proporcionalidad, que limita el esfuerzo exigible al profesional","La integridad, que protege la inviolabilidad del cuerpo humano","La continuidad, que impone no interrumpir nunca una atención"],["Esa modulación corresponde a la beneficencia, no a los principios europeos enumerados.","Por eso el consentimiento es esencial antes de toda intervención sobre el paciente.","La continuidad de la asistencia es una obligación deontológica distinta de esos principios."]],
  "136": ["¿Qué abarca el principio europeo de sinceridad y honestidad?",["Declarar al paciente los conflictos de interés que mantiene el profesional","Reconocer sus errores ante el equipo y ante la jerarquía","Dar al paciente y a su familia la información necesaria para decidir"],["La declaración de conflictos de interés es una obligación distinta de ese principio.","La confesión de los errores corresponde a la responsabilidad profesional, no a ese principio.","Es esencial en la comunicación entre el profesional y quienes deben pronunciarse."]],
  "137": ["¿Qué es un problema ético?",["Una situación en la que un valor o un principio se pone en cuestión","Una situación en la que dos principios se oponen y obligan a elegir","Una situación en la que el profesional conoce la solución pero no puede actuar"],["La discriminación en la asistencia sanitaria constituye un ejemplo.","Esa oposición caracteriza el dilema ético, mucho más complejo de resolver.","Esa imposibilidad de actuar define la angustia moral."]],
  "138": ["¿Qué caracteriza un dilema ético?",["Un valor se vulnera y hay que restablecer el principio desconocido","Dos principios se oponen y hay que elegir entre dos opciones ambas justas","El profesional duda entre una solución ventajosa y una solución justa"],["La puesta en cuestión de un solo valor define el problema ético.","Es una decisión entre «lo que es justo y lo que es justo», mucho más compleja que un problema ético.","Ese arbitraje corresponde a la tentación moral."]],
  "139": ["¿Qué es una situación de angustia moral?",["El profesional ignora qué conducta adoptar ante una situación inédita","El profesional sabe que hay valores amenazados pero elige ignorarlos","El profesional conoce la solución correcta pero unos obstáculos le impiden actuar"],["La incertidumbre sobre la solución no está en cuestión: la solución se conoce.","Ese retraimiento voluntario define la situación de silencio.","Esos obstáculos son externos, como la política de la institución, o internos, como el miedo o la inseguridad."]],
  "140": ["¿Cuál de estos obstáculos a la acción es un obstáculo interno?",["La inseguridad y el miedo que experimenta el propio profesional","La falta de tiempo que impone la organización del servicio","La burocracia excesiva y las normas internas del centro"],["La falta de sensibilización corresponde igualmente a los obstáculos internos.","La falta de tiempo es un obstáculo externo ligado a la institución.","Esas restricciones institucionales son obstáculos externos."]],
  "141": ["¿Qué es una situación de tentación moral?",["Hay que elegir entre dos opciones igualmente defendibles en el plano moral","Hay que elegir el bien antes que el mal, pero el mal procura una ventaja","Hay que actuar cuando la institución impide poner en práctica la solución"],["Esa equivalencia entre dos opciones justas caracteriza el dilema.","Es la ventaja personal esperada la que crea la tentación.","Ese impedimento exterior corresponde a la angustia moral."]],
  "142": ["¿Qué hace el profesional en una situación de silencio?",["Reconoce la conducta correcta pero se topa con obstáculos concretos","Elige el mal porque obtiene de él un beneficio personal directo","Sabe que hay valores en cuestión pero elige no tomar partido"],["Esa impotencia pese a la voluntad de actuar define la angustia moral.","Ese cálculo corresponde a la tentación moral.","Prefiere ignorar el problema antes que intervenir."]],
  "143": ["¿Por qué se afirma que toda toma de decisión es también una decisión ética?",["Porque la voluntad del paciente y sus preferencias deben tenerse siempre en cuenta","Porque cada decisión compromete la responsabilidad jurídica del profesional","Porque las políticas institucionales encuadran todas las decisiones que se toman"],["Las decisiones se apoyan en los datos científicos y en la experiencia, pero nunca al margen de la voluntad del paciente.","La responsabilidad jurídica es una consecuencia posible, no el fundamento de la afirmación.","Esas políticas son uno de los factores de la decisión, y no su dimensión ética."]],
  "144": ["¿Qué actitud se impone frente a los conflictos éticos, que son inevitables?",["Disolverlos para restablecer rápidamente la cohesión del equipo","Minimizarlos y resolverlos, sin buscar nunca disolverlos","Comunicarlos sistemáticamente a la dirección del centro"],["Disolver el conflicto equivale a negar su existencia en lugar de tratarlo.","Comprender la realidad del conflicto para tratarlo así constituye un imperativo moral.","La comunicación jerárquica no constituye la respuesta esperada."]],
  "145": ["¿En qué consiste el método deliberativo?",["Aplicar el principio que prevalece según una jerarquía preestablecida","Recoger la opinión del más experimentado de los miembros del equipo asistencial","Analizar los hechos, identificar las acciones posibles y después elegir la acción óptima"],["No se establece ninguna jerarquía a priori entre los principios en presencia.","La deliberación supone la confrontación de puntos de vista múltiples, no la autoridad de uno solo.","El razonamiento deliberativo es un proceso orientado a la toma de decisión."]],
  "146": ["¿Cuál es el alcance del razonamiento deliberativo?",["No aporta ninguna certeza y admite varias soluciones razonables","Desemboca en una solución única, demostrada como la única prudente","Garantiza que la decisión tomada será jurídicamente inatacable"],["Sigue siempre afectado por la incertidumbre, sin que la pluralidad de soluciones las vuelva imprudentes.","Es compatible con la pluralidad de soluciones a un mismo problema.","La conformidad con el derecho se verifica por separado, mediante la prueba de legalidad."]],
  "147": ["¿Qué requiere la deliberación con personas de puntos de vista diferentes?",["Mantenerse firmemente en su posición inicial para alimentar el debate","Una gran capacidad de escucha y de autoanálisis, y relativizar su punto de vista","Apartarse ante la opinión del participante más experimentado del grupo"],["Relativizar su propio punto de vista es precisamente lo que enriquece el proceder.","Discutir racionalmente las posiciones de los demás conduce a hacer evolucionar la propia visión del proceso.","La deliberación pone en interacción los puntos de vista, sin privilegiar ninguno de antemano."]],
  "148": ["¿Qué son las acciones extremas en el método deliberativo?",["Las que concilian mejor los valores en conflicto en la situación","Las que son manifiestamente ilegales y deben descartarse de entrada","Las que, al elegir un principio, sacrifican completamente el otro"],["Esas son al contrario las acciones intermedias, situadas entre los dos extremos.","El examen de la legalidad interviene en la fase de las pruebas de coherencia.","Sirven para enmarcar las acciones intermedias al identificar los límites que hay que rechazar."]],
  "149": ["¿Cuál es la acción óptima al término de la deliberación?",["La que menos daña los valores en conflicto y es la más prudente","La que respeta íntegramente el principio más importante en juego","La que obtiene la adhesión unánime de los miembros del grupo"],["Tiene en cuenta las circunstancias y las consecuencias; el mejor plan coincide con el más prudente.","Sacrificar el otro principio caracteriza una acción extrema, no la acción óptima.","La unanimidad no es el criterio: lo es la prudencia respecto a los valores."]],
  "150": ["¿Qué pruebas de coherencia hay que aplicar a la decisión adoptada?",["Eficacia, coste y aceptabilidad por la institución asistencial implicada","Estabilidad en el tiempo, publicidad y legalidad de la conducta elegida","Conformidad con el código deontológico y acuerdo del supervisor asistencial"],["Esos criterios de gestión no figuran entre las pruebas de coherencia.","Se verifica que se volvería a adoptar más adelante, que se defendería públicamente y que es conforme al derecho.","La prueba de legalidad cubre el derecho, sin exigir el acuerdo de la jerarquía."]],
  "151": ["¿Qué verifica la prueba de estabilidad en el tiempo?",["Si la decisión seguirá siendo aplicable a pesar de la evolución de la legislación","Si el estado del paciente permitirá mantener la conducta elegida","Si se tomaría la misma decisión tras cierto tiempo de distancia"],["La prueba no versa sobre la perdurabilidad jurídica de la solución.","La evolución clínica no es el objeto de esa prueba.","Permite evaluar si la decisión se tomó bajo la influencia de las emociones que suscitó el caso."]],
  "152": ["En el proceso de decisión, ¿a qué principio remite la pregunta «¿qué no hay que hacer en ningún caso?»",["A la no maleficencia","A la beneficencia","A la justicia"],["Esa pregunta abre el proceso al fijar de entrada lo que queda excluido.","La beneficencia responde a la pregunta de qué es lo mejor para el paciente.","La justicia responde a qué dañaría gravemente a la sociedad o a terceros."]],
  "153": ["¿Qué conflictos éticos genera la creciente complejidad de la asistencia?",["Únicamente entre el profesional y el paciente que atiende","Entre profesionales, con el paciente, con la familia o con el centro","Únicamente entre los distintos profesionales de un mismo equipo"],["Los conflictos recogidos implican también a las familias, a los equipos y a la institución.","El propio paciente puede entrar igualmente en conflicto con la institución que lo atiende.","Esa es solo una de las cinco configuraciones identificadas."]],
  "154": ["¿Qué ventaja ofrece el consultor en ética clínica respecto al comité?",["Un poder de decisión vinculante para el equipo que lo solicita","Una competencia jurídica que permite validar la legalidad del acto","Más proximidad y capacidad de reacción, lo más cerca posible de la práctica cotidiana"],["Como el comité, ilumina la decisión sin sustituir a los profesionales.","Su ámbito es la ética clínica, no el peritaje jurídico.","Localizable de forma permanente, permite tratar un conflicto urgente sin esperar una reunión formal."]],
  "155": ["¿En qué servicios resulta más útil recurrir a un consultor en ética?",["En los de alta carga ética: cuidados intensivos, urgencias, oncología y paliativos","En los servicios de consulta externa con alto volumen de pacientes","En los servicios administrativos encargados de la gestión de los ingresos"],["Los conflictos frecuentes versan allí sobre la capacidad del paciente, la futilidad y la limitación del esfuerzo terapéutico.","El volumen de actividad no determina la densidad de los conflictos éticos.","Esos servicios no toman decisiones clínicas que impliquen conflictos de valores."]],
  "156": ["¿Cuál es el alcance de los protocolos de ética clínica?",["Reglas obligatorias que se imponen a los profesionales del centro","Un marco de referencia común, sin carácter normativo ni sustitución del juicio","Documentos reservados a los miembros del comité de ética del centro"],["Precisamente, no tienen ningún carácter normativo.","Proponen recomendaciones estructuradas frente a conflictos recurrentes, como el rechazo del tratamiento.","Están destinados a los profesionales, aunque sigan siendo poco utilizados."]],
  "157": ["¿Por qué se utilizan poco los protocolos de ética clínica?",["Su aplicación compromete la responsabilidad personal del profesional","Su redacción está reservada únicamente a las sociedades científicas internacionales","Se desconoce su existencia o los matices del caso parecen no encajar en ellos"],["No hay ninguna responsabilidad particular ligada a su uso.","Los elaboran los comités, los servicios, las sociedades o los colegios profesionales.","Los profesionales estiman a veces que la singularidad de la situación escapa al marco previsto."]],
  "158": ["¿Cuál es el papel del mediador o facilitador ético?",["Permanecer neutral, facilitar el diálogo y velar por que el paciente sea escuchado","Zanjar el conflicto designando a la parte cuya posición debe prevalecer","Representar al centro en la negociación con la familia del paciente"],["No impone ninguna solución: acompaña la búsqueda de un acuerdo entre las partes.","No decide y se limita a facilitar el acuerdo entre las partes.","Su neutralidad le impide representar a una de las partes en presencia."]],
  "159": ["¿Por qué da el mediador ético la palabra principalmente al paciente?",["Porque la ley le confiere un derecho de prioridad en la discusión","Porque es el actor más vulnerable entre las partes en presencia","Porque es el único que puede describir objetivamente la situación clínica"],["Ninguna regla de prioridad jurídica fundamenta esa atención particular.","Su neutralidad no impide velar de forma particular por el respeto de sus intereses y de sus valores.","El equipo asistencial aporta igualmente una descripción de la situación."]],
  "160": ["¿Qué es un comité de ética en un centro sanitario?",["Una instancia disciplinaria que sanciona los incumplimientos de los profesionales","Un órgano de dirección que arbitra la asignación de los recursos del servicio","Un espacio consultivo interdisciplinar, confidencial, de dictámenes no vinculantes"],["La sanción disciplinaria corresponde al colegio profesional.","La asignación de los recursos corresponde a la gestión del centro.","Sus miembros no deciden en lugar de los profesionales: les ayudan a avanzar."]],
  "161": ["¿Cuál de estos objetivos no figura entre los de los comités de ética?",["Evaluar el rendimiento de los servicios con indicadores de calidad","Asesorar a profesionales, ciudadanos y administraciones frente a los conflictos éticos","Promover la formación en bioética del personal y de sus propios miembros"],["Sus objetivos versan sobre la reflexión, el asesoramiento, la sensibilización y la formación.","Esa función de asesoramiento figura explícitamente entre sus objetivos.","La formación, incluida la de los miembros del comité, forma parte de sus objetivos."]],
  "162": ["¿Cuál es la misión de un espacio de reflexión ética regional?",["Instruir las reclamaciones presentadas por los usuarios contra los centros","Desarrollar una cultura ética en su región, entre los profesionales y el público","Autorizar los protocolos de investigación realizados en los centros de la región"],["La tramitación de las reclamaciones corresponde a otras instancias.","Reúne al conjunto de los centros y actores del territorio en torno a esa reflexión.","Esa autorización corresponde a los comités de protección de las personas."]],
  "163": ["¿Bajo qué responsabilidad funcionan los espacios de reflexión ética regionales?",["Bajo la de los colegios profesionales de cada una de las regiones implicadas","Bajo la de los hospitales universitarios de su territorio","Bajo la de las agencias regionales de salud, con un informe anual público"],["Los colegios no ejercen la tutela de esos espacios.","Su adscripción es regional y no hospitalaria.","Ese informe se dirige al comité consultivo nacional de ética, que elabora una síntesis de él."]],
  "164": ["¿Qué aspecto esencial caracteriza un conocimiento científico?",["La posibilidad de ser refutado por argumentos y hechos posteriores","La certeza definitiva que aporta una vez establecida la prueba","El reconocimiento que obtiene en la comunidad de expertos"],["Todo investigador debe conservar un espíritu crítico hacia sus propias conclusiones y permanecer abierto a la impugnación.","Una proposición no susceptible de ser impugnada escapa precisamente al ámbito científico.","La adhesión de los pares no garantiza por sí sola el carácter científico de un enunciado."]],
  "165": ["¿Qué deber tiene el investigador hacia la comunidad científica?",["Respetar la dignidad y la autonomía de las personas que participan en el estudio","Comunicar honestamente sus resultados, sin conflicto de interés ni influencia del financiador","Utilizar los recursos y las instalaciones de manera responsable"],["Ese deber existe, pero se ejerce hacia los participantes, no hacia la comunidad científica.","Esa transparencia enriquece el saber común y protege la integridad de los conocimientos producidos.","Ese uso responsable constituye un deber hacia la sociedad."]],
  "166": ["¿Qué es una pseudociencia?",["Una práctica que busca curar por medios sin prueba, a veces peligrosa","Una hipótesis científica que todavía no se ha confirmado con estudios","Un conjunto de afirmaciones presentadas como científicas sin haberlo sido probado"],["Esa descripción corresponde a la pseudoterapia, que es su aplicación a la asistencia.","Una hipótesis en curso de evaluación corresponde al proceso normal de la ciencia.","Creencias, métodos y prácticas se presentan en ella falsamente como validados por un método reconocido."]],
  "167": ["¿Qué es una pseudoterapia?",["Una práctica asistencial basada en criterios sin prueba científica actualizada","Una técnica cuya eficacia está en curso de evaluación científica","Una terapia eficaz pero aún no financiada por el sistema de salud"],["Puede presentar un riesgo significativo, e incluso un peligro, para la persona que se somete a ella.","Una técnica en curso de evaluación se distingue de aquella cuyos fundamentos se han descartado.","La financiación es una cuestión económica, sin relación con la validez científica."]],
  "168": ["¿Cómo atenta el recurso a las pseudoterapias contra la autonomía?",["Al sustituir una terapia cuya eficacia está científicamente establecida","Al no facilitar información precisa sobre la eficacia de la técnica","Al aprovecharse de la vulnerabilidad de las personas que recurren a ellas"],["Esa sustitución atenta contra el principio de beneficencia.","Sin información exacta, la decisión del paciente no puede ser libre ni informada.","Esa explotación de la vulnerabilidad pone en cuestión el principio de justicia."]],
  "169": ["¿Cómo atenta el recurso a las pseudoterapias contra la no maleficencia?",["Al apartar al paciente de una terapia basada en pruebas científicas","Al no facilitar una información exacta sobre la eficacia de la técnica","Al ser capaz de causar un perjuicio al paciente sabiéndolo"],["Esa privación de un cuidado útil corresponde al principio de beneficencia.","Ese defecto de información constituye un atentado contra la autonomía.","El carácter deliberado de la exposición al riesgo agrava el atentado contra el principio."]],
  "170": ["¿Por qué exige la investigación protecciones superiores a las de la asistencia?",["Su finalidad es el avance de los conocimientos, no el beneficio de cada participante","Hace intervenir técnicas más peligrosas que la asistencia corriente","La realizan investigadores menos formados que los clínicos"],["Hay que evitar considerar al paciente un simple instrumento al servicio de la finalidad científica.","El grado de riesgo varía según los estudios y no fundamenta la diferencia de régimen.","La competencia de los investigadores es al contrario una exigencia ética del estudio."]],
  "171": ["¿Qué diferencia separa la finalidad de la asistencia de la de la investigación?",["En la asistencia el beneficio es inmediato; en la investigación es diferido","En la asistencia el paciente es un fin en sí; en la investigación se busca el saber","En la asistencia se requiere el consentimiento; en la investigación es facultativo"],["El beneficio de la investigación puede no llegar nunca a los propios participantes.","La investigación selecciona un grupo para obtener conocimientos generalizables a una población amplia.","El consentimiento informado se refuerza al contrario en el marco de la investigación."]],
  "172": ["¿De dónde procede el texto fundador de diez criterios en ética de la investigación?",["De una asamblea de la asociación médica mundial reunida en Helsinki","De una comisión nacional creada tras la revelación de un estudio sobre la sífilis","Del juicio de los experimentos realizados con presos en los campos"],["Esa asamblea produjo la declaración destinada a los investigadores, posterior a ese texto.","Esa comisión produjo el informe fundador de los principios de la bioética.","El tribunal estableció diez criterios que permiten determinar si un experimento se ha realizado éticamente."]],
  "173": ["¿Cuál es el objeto de la declaración de Helsinki?",["Definir las obligaciones mínimas de los investigadores hacia los participantes","Fijar las normas de buenas prácticas de fabricación de los medicamentos","Organizar el reconocimiento mutuo de los títulos entre países miembros"],["Revisada con regularidad, constituye la referencia en materia de investigación en seres humanos.","La calidad farmacéutica corresponde a normas distintas de las de la ética de la investigación.","Ese texto no versa en absoluto sobre el ejercicio ni la formación de los profesionales."]],
  "174": ["¿Qué precisa la declaración de Helsinki sobre la finalidad de la investigación?",["El beneficio colectivo esperado justifica una limitación de los derechos individuales","Generar conocimientos no puede nunca prevalecer sobre los derechos de los participantes","Los derechos de los participantes ceden cuando la enfermedad estudiada es grave"],["Esa es exactamente la posición que el texto descarta.","La responsabilidad de proteger a los participantes incumbe siempre a los médicos o a los demás investigadores.","Ninguna gravedad permite hacer prevalecer el objetivo científico sobre los derechos."]],
  "175": ["¿Qué traduce concretamente el principio de autonomía en un protocolo de investigación?",["La demostración de que los riesgos están justificados por los beneficios esperados","La selección de los participantes con criterios científicos y no de comodidad","La obtención de un consentimiento informado y la confidencialidad de los datos"],["Esa demostración responde al principio de no maleficencia.","Esa exigencia de representatividad corresponde al principio de justicia.","La persona debe recibir una información suficiente y comprensible, y decidir libremente."]],
  "176": ["¿Cuál de estas medidas no corresponde a la confidencialidad de los datos de investigación?",["La publicación íntegra de los datos brutos recogidos de los participantes","La atribución de un código a cada participante para disociar identidad y datos","La minimización del volumen de los datos recogidos para el estudio"],["Las medidas previstas son la anonimización, la limitación de acceso, la seguridad, la minimización y el consentimiento.","Esa es la pseudonimización, expresamente citada entre las medidas esperadas.","Recoger solo lo necesario forma parte de las medidas de protección."]],
  "177": ["¿Cómo se traduce el principio de beneficencia en el diseño de un estudio?",["En la entrega a los participantes de una compensación que cubra sus cargas","En una pregunta válida, un diseño adecuado, un tamaño muestral y unos investigadores competentes","En la garantía de que cada participante obtendrá un beneficio directo del estudio"],["La compensación no garantiza en absoluto el interés científico del estudio.","Lo que no es científicamente correcto no puede ser éticamente aceptable.","La investigación no implica siempre un beneficio directo para quienes participan en ella."]],
  "178": ["¿En qué condiciones se autoriza el recurso a un placebo en investigación?",["Siempre que los participantes hayan sido informados de su posible asignación","En todo estudio comparativo, para garantizar la validez de los resultados","En las enfermedades benignas y en ausencia de un tratamiento eficaz establecido"],["La información no basta: la restricción depende de la naturaleza de la enfermedad y de los tratamientos existentes.","La exigencia metodológica no prima sobre la protección de los participantes.","Esa restricción se deriva de la exigencia de una relación beneficio-riesgo favorable."]],
  "179": ["¿Cómo encuadra el principio de justicia la selección de los participantes?",["Con criterios científicos, con una población representativa de la patología","Privilegiando a las personas disponibles y fáciles de seguir en el tiempo","Excluyendo sistemáticamente a las poblaciones socialmente desfavorecidas"],["La comodidad del reclutamiento o la vulnerabilidad de las personas no pueden fundamentar la selección.","La comodidad es precisamente uno de los criterios que ese principio descarta.","Excluirlas equivaldría a privarlas de los beneficios de la investigación."]],
  "180": ["¿Qué abarca la exigencia de valor social o científico de un estudio?",["Garantizar que los resultados se publicarán en una revista con revisión por pares","Evaluar una intervención o una teoría capaz de mejorar la salud o el saber","Asegurar que el estudio responde a una demanda expresada por los pacientes"],["La difusión es una obligación distinta, que interviene al término del estudio.","Se justifica por la escasez de los recursos y por la necesidad de evitar el despilfarro.","El interés científico no depende del origen de la pregunta planteada."]],
  "181": ["¿Qué busca la exigencia de evaluación independiente de un protocolo?",["Hacer verificar los resultados por un segundo equipo tras el final del estudio","Hacer validar la metodología por el financiador de la investigación","Hacer examinar el protocolo por personas ajenas al estudio"],["La evaluación versa sobre el protocolo antes de su puesta en marcha, no sobre los resultados.","Se busca precisamente la independencia económica respecto al financiador.","Minimiza los conflictos de interés y responde al compromiso de rendir cuentas al público."]],
  "182": ["¿Cuál de estas manifestaciones no corresponde al respeto de los participantes incluidos?",["La garantía de que el tratamiento recibido se mantendrá tras el final del estudio","La posibilidad de retirarse libremente de la investigación en cualquier momento","La comunicación de los riesgos o beneficios descubiertos durante el estudio"],["Las manifestaciones previstas son la retirada libre, la confidencialidad, la información y el seguimiento del bienestar.","Ese derecho de retirada figura en primer lugar en el respeto debido a los participantes.","Esa información durante el estudio forma parte de las obligaciones hacia los participantes."]],
  "183": ["¿Cuál es el alcance del dictamen que emite un comité de protección de las personas?",["Formula una recomendación que el promotor puede decidir seguir","Su autorización es indispensable antes de iniciar cualquier estudio en humanos","Solo interviene en caso de litigio surgido durante la investigación"],["Su dictamen condiciona la realización del estudio, al contrario que los comités de ética clínica.","No se trata de un simple comité consultivo: su dictamen condiciona el inicio de la investigación.","Se pronuncia antes del comienzo del estudio, y no en caso de litigio."]],
  "184": ["¿Sobre qué versa la evaluación que realiza un comité de protección de las personas?",["Únicamente la calidad estadística del plan de análisis que propone el promotor","La capacidad financiera del promotor para llevar el estudio hasta su término","El protocolo, la información entregada, la pertinencia, las instalaciones y los investigadores"],["El análisis estadístico es solo uno de los elementos que se examinan.","La solidez financiera del promotor no entra en el ámbito de su evaluación.","El conjunto busca garantizar el respeto de la dignidad del paciente y su seguridad."]],
  "185": ["¿Cuál es el método de trabajo de los comités de protección de las personas?",["La deliberación, en el seno de una instancia multidisciplinar y pluralista","El voto por mayoría simple de los miembros presentes en la sesión","La aplicación de una tabla de criterios que rellena un único ponente"],["La confrontación de puntos de vista variados fundamenta la calidad del dictamen emitido.","El modo de decisión no es lo que caracteriza su metodología.","Encomendar el examen a un único ponente contradiría el carácter colegiado de la instancia."]],
  "186": ["Además del dictamen del comité, ¿en qué casos se requiere una autorización de la agencia del medicamento?",["Para toda investigación en seres humanos, sin distinción","Para los medicamentos y los productos sanitarios sin marcado reglamentario","Únicamente para los estudios observacionales sobre datos existentes"],["Esa autorización adicional solo atañe a determinadas categorías de estudios.","También lo es para un producto con marcado empleado al margen de su uso previsto y aprobado.","Los estudios sin intervención no corresponden a esa autorización."]],
  "187": ["¿Qué garantiza el marcado reglamentario que figura en un producto sanitario?",["Que ha demostrado su eficacia en un ensayo controlado aleatorizado","Que está financiado por el sistema público de aseguramiento sanitario","Que ha sido aprobado por un organismo de control competente"],["El marcado acredita una conformidad controlada, no un nivel de prueba clínica.","La financiación procede de una decisión distinta de la conformidad técnica.","Su ausencia impone una autorización adicional antes de todo ensayo clínico."]],
  "188": ["¿Qué obligación pesa sobre los investigadores una vez terminado el estudio?",["Poner los resultados a disposición de la comunidad científica","Destruir el conjunto de los datos recogidos de los participantes","Proponer a los participantes continuar el tratamiento experimental"],["Son responsables de la exhaustividad y de la exactitud de sus informes.","Los datos son objeto de reglas de conservación, no de una destrucción sistemática.","No se prevé ninguna obligación general de continuar el tratamiento por ese motivo."]],
  "189": ["¿Cuál de estas obligaciones no corresponde a la ética de la publicación?",["Publicar tanto los resultados positivos como los negativos","Reservar la primicia de los resultados al financiador del estudio","No divulgar prematuramente resultados de eficacia no probados"],["Ocultar los resultados negativos falsea el estado de los conocimientos disponibles.","Las obligaciones previstas imponen al contrario transparencia y declaración de las fuentes de financiación.","Esa contención evita inducir a error a los profesionales y al público."]],
  "190": ["¿Por qué es la publicación de los resultados negativos una obligación ética?",["Porque la ley obliga a publicar todo trabajo que haya recibido financiación","Porque los comités exigen la publicación antes de cerrar el expediente","Porque ocultar esos resultados falsea el estado de los conocimientos disponibles"],["La obligación es ética y no depende del origen de la financiación.","El cierre administrativo del expediente no es lo que fundamenta esa obligación.","Los investigadores responden de la exhaustividad tanto como de la exactitud de sus informes."]],
  "191": ["¿Qué abarca la prohibición de inventar, falsificar o suprimir resultados?",["Un atentado directo contra la integridad científica del investigador","Un incumplimiento del respeto debido a los participantes incluidos en el estudio","Una violación de las reglas de confidencialidad de los datos personales"],["Se añade al plagio y a la publicidad engañosa entre los incumplimientos prohibidos.","El respeto de los participantes atañe a su retirada, a su vida privada y a su información.","La confidencialidad protege la identidad de las personas, no la veracidad de los resultados."]],
  "192": ["¿Qué cambio de marco refleja el consentimiento informado?",["El paso de una relación vertical fundada en la beneficencia a una relación horizontal","El paso de una responsabilidad colectiva a una responsabilidad individual del profesional","El paso de una información oral a una información sistemáticamente escrita"],["Se ha pasado del «todo para el paciente, pero sin el paciente» a una decisión fundada en su autonomía.","El cambio versa sobre quién decide, no sobre la imputación de la responsabilidad.","La información sigue facilitándose por regla general de forma verbal."]],
  "193": ["¿De qué forma se facilita por regla general la información al paciente?",["Mediante un documento escrito entregado contra firma antes de todo acto","Verbalmente, con mención en la historia clínica","A través del médico de familia, que la transmite después"],["El escrito viene a complementar el intercambio oral, que sigue siendo la regla.","Un documento escrito puede complementarla para que el paciente pueda consultarla.","Cada profesional está obligado a informar él mismo al paciente que atiende."]],
  "194": ["¿A quién incumbe la obligación de informar al paciente?",["Únicamente al médico responsable de la atención del paciente","Al centro, que organiza la entrega de la información a los usuarios","A todo profesional sanitario, cualquiera que sea su lugar y su modo de ejercicio"],["Cada profesional responde personalmente de la información relativa a sus actos.","La obligación es personal y no puede transferirse a la institución.","En ningún caso puede descargarla en un colega, ejerza en el ámbito privado o público."]],
  "195": ["¿Quién es titular del derecho a la información sobre la asistencia?",["El paciente, y los allegados solo se informan si él lo permite expresa o tácitamente","El paciente y su familia cercana, que se informan en las mismas condiciones","El representante legal desde el momento en que el paciente ingresa"],["Es el paciente capaz y libre quien decide compartir o no los datos sobre su estado de salud.","Los allegados solo se informan en la medida en que el paciente lo autoriza.","El representante solo interviene en las situaciones de incapacidad previstas por la ley."]],
  "196": ["¿Cómo informar a un paciente cuyo estado altera la comprensión?",["Absteniéndose de informarle y dirigiéndose únicamente al representante legal","De manera adaptada a sus capacidades, informando también a su representante legal","Posponiendo la información hasta el restablecimiento de sus facultades"],["El paciente debe ser informado de una manera adaptada a sus capacidades de comprensión.","La incapacidad no priva nunca al paciente de su derecho a ser informado.","La información no puede posponerse más allá del momento en que debe tomarse la decisión."]],
  "197": ["¿Qué hacer cuando el médico estima que el paciente no está en condiciones de comprender?",["Acudir sistemáticamente al juez para que designe un representante","Consignar la imposibilidad en la historia y continuar la asistencia sin informar","Comunicar la información a las personas vinculadas por lazos familiares o de hecho"],["La intervención del juez solo se requiere en situaciones particulares previstas por la ley.","La información debe facilitarse a los allegados, y no simplemente omitirse.","Esa transmisión suple la imposibilidad de informar útilmente al propio paciente."]],
  "198": ["¿Cuál de estas informaciones no entra en el contenido debido al paciente?",["El coste detallado de cada acto y su nivel de cobertura","Los riesgos frecuentes o graves normalmente previsibles del acto propuesto","Las consecuencias previsibles en caso de rechazo del acto propuesto"],["La información versa sobre la utilidad, la urgencia, las consecuencias, los riesgos y las alternativas.","Esos riesgos forman parte del contenido expresamente previsto.","Informar sobre las consecuencias de un rechazo permite al paciente decidir con conocimiento de causa."]],
  "199": ["¿Qué debe hacer el profesional si aparecen riesgos nuevos después del acto?",["Mencionarlos en la historia sin tener que informar al paciente","Informar a la persona afectada, salvo si resulta imposible localizarla","Informar únicamente al médico de familia, que valorará la oportunidad"],["La historia no sustituye la información debida a la persona afectada.","Esa obligación de información se prolonga por tanto después de la ejecución del acto.","La información se debe directamente al paciente, no filtrada por un colega."]],
  "200": ["¿Puede el paciente negarse a recibir la información que le concierne?",["No, la información es una obligación a la que no puede sustraerse","Sí, y esa renuncia le exime entonces de consentir al acto","Sí, su voluntad se respetará y se consignará en la historia clínica"],["Toda persona tiene derecho al respeto de su voluntad de no ser informada.","La renuncia a la información no exime nunca de recoger el consentimiento.","El consentimiento previo a la intervención debe, no obstante, obtenerse a pesar de esa renuncia."]],
  "201": ["¿Por qué está limitada la renuncia del paciente a ser informado?",["Por el interés del paciente, de terceros o de la colectividad, y por las exigencias del caso","Únicamente por la gravedad de la patología que padece el paciente","Por el acuerdo previo del representante legal o de la persona de confianza"],["Esos límites impiden que la ignorancia elegida dañe a otros o comprometa el tratamiento.","La gravedad no es en sí un límite: son los intereses en presencia los que lo fundamentan.","No se requiere el acuerdo de ningún tercero para que esa voluntad se respete."]],
  "202": ["¿Qué significa que el consentimiento deba ser libre?",["El paciente debe comprender el alcance exacto del acto al que consiente","Se obtiene sin presión, amenaza, coacción ni promesa, vengan de donde vengan","El paciente debe poder elegir libremente al profesional que le interviene"],["Esa exigencia de comprensión define el carácter informado del consentimiento.","Esas presiones pueden provenir del profesional, de la familia o del entorno.","La libre elección del profesional es un derecho distinto de la libertad del consentimiento."]],
  "203": ["¿Puede cuestionarse el consentimiento ya dado?",["No, una vez firmado compromete al paciente durante toda la duración del tratamiento","Sí, pero únicamente antes del inicio material de la intervención prevista","Sí, el paciente puede retirarlo en cualquier momento"],["La revocabilidad en cualquier momento es un carácter esencial del consentimiento.","La posibilidad de retirada no está encerrada en ese límite temporal.","Ningún acto ni tratamiento puede practicarse sin un consentimiento libre e informado mantenido."]],
  "204": ["¿Qué abarca el carácter leal de la información?",["El paciente no debe ser engañado, salvo omisión justificada por una exigencia terapéutica","El lenguaje debe ajustarse al nivel intelectual y cultural del destinatario","La información debe facilitarse con suficiente antelación para permitir la reflexión"],["Esa omisión solo se concibe si el conocimiento de la enfermedad pudiera dañar gravemente su salud.","Esa adaptación del lenguaje define el carácter claro de la información.","El momento de la entrega corresponde al carácter adaptado de la información."]],
  "205": ["¿Qué significa que la información deba ser clara?",["Todo vocabulario técnico debe desterrarse sistemáticamente del intercambio","El lenguaje se ajusta al destinatario, y lo técnico se admite si se explica","La información debe caber en un número limitado de frases cortas"],["El lenguaje técnico sigue siendo posible siempre que se explique de forma sencilla.","Las acciones del proceso asistencial deben exponerse al paciente de forma clara y sencilla.","La brevedad no es el criterio establecido: lo es la inteligibilidad para el destinatario."]],
  "206": ["¿A qué debe adaptarse la información?",["Únicamente al nivel de estudios del paciente y a su profesión de origen","Al tiempo disponible para la consulta en la organización del servicio","A las circunstancias personales, al momento oportuno y al objetivo perseguido"],["La adaptación versa sobre la edad, el estado de ánimo y las circunstancias, no solo sobre el nivel de instrucción.","Las restricciones organizativas no pueden determinar el contenido de la información.","Se da con bastante antelación para permitir la reflexión, y varía según se trate de informar o de obtener un acuerdo."]],
  "207": ["¿Qué límite se impone en cualquier caso a la entrega de la información?",["Nunca debe orientarse hacia una decisión concreta ni manipular al paciente","Nunca debe versar sobre los riesgos poco frecuentes del procedimiento","Nunca debe comunicarse en presencia de un acompañante"],["La información ilumina la elección del paciente; no la conduce.","Los riesgos raros pero graves forman parte del contenido debido al paciente.","La presencia de un acompañante es posible siempre que el paciente lo desee."]],
  "208": ["¿En qué consiste el privilegio terapéutico?",["Reservar al médico la elección de la técnica aplicada al paciente","Limitar la información cuando pudiera dañar gravemente la salud del paciente","Eximir al profesional de recoger el consentimiento del paciente"],["La elección de la técnica corresponde a la libertad terapéutica, no al privilegio.","Ese caso excepcional supone que objetivamente no convenga informar a la persona.","El consentimiento sigue siendo necesario: solo se limita la extensión de la información."]],
  "209": ["¿Qué obligaciones acompañan al recurso al privilegio terapéutico?",["Obtener el dictamen previo del comité de ética del centro","Hacer firmar al paciente una renuncia escrita a su derecho a ser informado","Consignar en la historia los motivos, lo que se dice y lo que se omite, e informar a los allegados"],["No se exige ninguna consulta previa a un comité en ese caso.","La renuncia del paciente es una situación distinta del privilegio terapéutico.","Los allegados reciben una información que menciona la exigencia terapéutica, para no revelar lo que se ha omitido."]],
  "210": ["¿Cómo verifica el profesional que la información se ha comprendido?",["Pidiendo, por ejemplo, a la persona que repita lo que ha entendido","Haciéndole firmar un certificado de buena comprensión","Entregándole un folleto detallado sobre el procedimiento previsto"],["La invita igualmente a expresarse y a plantear preguntas sobre lo que se le ha dicho.","Una firma no acredita que el contenido se haya asimilado realmente.","El documento escrito complementa el intercambio, pero no basta para verificar la comprensión."]],
  "211": ["¿Quién puede ser designado persona de confianza?",["Únicamente un miembro de la familia en primer grado del paciente","Un familiar, un allegado o el médico de familia, por cualquier persona mayor de edad","Únicamente un profesional sanitario ajeno al equipo asistencial"],["La elección se extiende a los allegados y puede recaer en el médico de familia.","La designación se hace por escrito y sigue siendo revocable en cualquier momento.","La persona de confianza puede ser un allegado sin condición profesional."]],
  "212": ["¿Cuál es el papel de la persona de confianza?",["Decidir en lugar del paciente desde que ha sido designada por escrito","Recibir el conjunto de la información médica en paralelo al paciente","Ser consultada si el paciente ya no puede expresar su voluntad, y acompañarle si él lo desea"],["Se la consulta para que testimonie la voluntad del paciente; no lo sustituye.","Solo es destinataria de la información cuando el paciente no está en condiciones de recibirla.","Puede asistir a las entrevistas médicas para ayudarle en sus decisiones."]],
  "213": ["¿Qué debe hacer el profesional en caso de urgencia o de imposibilidad de localizar a los allegados?",["Intervenir como juzgue necesario en el interés del paciente","Posponer la intervención hasta que pueda contactarse con un allegado","Acudir a la autoridad judicial para obtener una autorización de intervenir"],["La urgencia constituye una de las excepciones a la recogida previa del consentimiento.","Esperar expondría al paciente a un perjuicio que la excepción busca precisamente evitar.","La intervención judicial es incompatible con la urgencia de la situación."]],
  "214": ["¿En qué plazo debe informarse a la autoridad judicial de un internamiento obligatorio?",["En un plazo máximo de setenta y dos horas","En un plazo máximo de veinticuatro horas","En un plazo máximo de ocho días desde la medida"],["El plazo previsto es más breve, para asegurar un control rápido de la medida.","Ese control acompaña las medidas adoptadas por un motivo de salud pública previsto por la ley.","Un plazo así privaría al control judicial de su efecto protector."]],
  "215": ["¿A quién consultar cuando el paciente está inconsciente y no puede consentir?",["Al médico de familia habitual, que conoce mejor sus antecedentes","Al supervisor asistencial del servicio, responsable de la organización de los cuidados","A la persona de confianza designada y, en su defecto, a la familia o a un allegado"],["El médico de familia puede haber sido designado persona de confianza, pero no tiene ese papel por derecho.","La jerarquía asistencial no tiene ninguna condición para expresar la voluntad del paciente.","Testimonian la voluntad expresada anteriormente por el paciente."]],
  "216": ["¿Para cuál de estas situaciones exige la ley un consentimiento escrito?",["La investigación en seres humanos","Toda intervención quirúrgica practicada con anestesia general","Todo ingreso de una duración superior a veinticuatro horas"],["El escrito se exige igualmente para la interrupción voluntaria del embarazo y la donación de gametos.","En Francia la ley no impone el escrito para una intervención quirúrgica, aunque se aconseje.","La duración del ingreso no es un criterio de exigencia del escrito."]],
  "217": ["¿Qué puede decirse de los formularios de consentimiento generales?",["Se admiten cuando se complementan con una explicación oral","No son aceptables ni en el plano ético ni en el plano jurídico","Se admiten para los actos que no presentan riesgo grave"],["Ninguna explicación oral compensa el carácter general del documento.","El formulario debe ser específico para cada procedimiento previsto.","La especificidad se exige cualquiera que sea la gravedad del acto."]],
  "218": ["¿Qué condiciones rodean la entrega del formulario de consentimiento?",["Entregarse en el momento del acto, para que la información siga presente en la mente","Entregarse por el personal administrativo en el ingreso del paciente","Entregarse con tiempo para leerlo y discutirlo, por una persona vinculada a la técnica"],["El documento debe al contrario presentarse con suficiente antelación para permitir la reflexión.","Debe obtenerlo personal directamente vinculado a la técnica o al tratamiento.","Debe además revisarse tras su aplicación o si el proceso lo exige."]],
  "219": ["¿Cuál de estas menciones no figura entre los datos mínimos del formulario?",["El pronóstico cifrado de éxito del procedimiento previsto","La declaración del paciente de que sabe que puede revocar su consentimiento","Las alternativas razonables al procedimiento propuesto al paciente"],["Los datos previstos cubren descripción, objetivo, beneficios, alternativas, riesgos y contraindicaciones.","Esa mención recuerda que la revocación es posible sin tener que indicar su causa.","La existencia de otras soluciones forma parte de los datos mínimos exigidos."]],
  "220": ["¿En cuál de estos casos se otorga el consentimiento por representación?",["Cuando el estado del paciente no le permite hacerse cargo de su situación","Cuando el paciente rechaza el tratamiento que el profesional juzga indicado","Cuando el paciente pide no recibir la información que le concierne"],["El médico responsable valora esa incapacidad; a falta de representante legal, consienten los allegados.","Un rechazo informado es la expresión de la autonomía, no una incapacidad para decidir.","La renuncia a la información no priva al paciente de su capacidad de consentir."]],
  "221": ["¿En qué criterio debe fundarse la decisión tomada por representación?",["La voluntad personal del representante, que compromete su responsabilidad","El mayor interés para la vida o la salud del paciente representado","La opinión mayoritaria de los miembros de la familia presentes junto al paciente"],["El representante no expresa su propia voluntad, sino que protege el interés del paciente.","Las decisiones contrarias a ese interés deben llevarse ante la autoridad judicial.","Ninguna regla de mayoría familiar gobierna la decisión."]],
  "222": ["¿Qué hacer si la urgencia impide obtener la autorización judicial requerida?",["Abstenerse hasta obtener la autorización, para evitar toda imputación","Recoger el acuerdo escrito de dos profesionales del equipo asistencial","Adoptar las medidas necesarias para salvaguardar la vida o la salud del paciente"],["La abstención expondría al paciente a un perjuicio que la ley busca precisamente prevenir.","Ningún procedimiento de doble firma suple la autorización judicial.","Los profesionales quedan entonces protegidos por el cumplimiento de un deber y el estado de necesidad."]],
  "223": ["¿A quién deben informar las autoridades sanitarias en caso de negativa parental a un cuidado vital?",["Al juez de familia, directamente o a través del ministerio fiscal","Al colegio profesional al que pertenece el profesional que atiende al niño","A los servicios policiales, que deciden la conducta que hay que seguir con urgencia"],["La información es inmediata para que la decisión se tome en el interés superior del menor.","El colegio profesional no tiene competencia para arbitrar una decisión asistencial.","La protección del menor corresponde a la autoridad judicial, no a los servicios policiales."]],
  "224": ["¿Cómo se recoge el consentimiento para un niño de menos de doce años?",["Por el propio niño para los actos sin riesgo grave para su salud","Por los representantes legales, después de escuchar la opinión del niño","Por el profesional sanitario, que valora por sí solo el interés del niño"],["Esa posibilidad solo se abre a partir de la edad en que puede reconocerse la madurez.","No tiene la capacidad intelectual y emocional reconocida para captar el alcance de un acto médico.","El profesional evalúa la capacidad del menor, pero nunca consiente en su lugar."]],
  "225": ["¿Qué es la figura del menor maduro?",["El menor de más de dieciséis años, habilitado para consentir a todos los actos","El menor emancipado por resolución judicial antes de su mayoría de edad civil","El menor juzgado capaz de captar el alcance del acto decide sobre los cuidados sin riesgo grave"],["A esa edad, los actos de riesgo grave corresponden todavía al consentimiento por representación.","La emancipación es un estatus jurídico distinto de la apreciación de la madurez.","Es el profesional quien asume la responsabilidad científica y moral de evaluar esa capacidad."]],
  "226": ["¿De qué depende la capacidad que se reconoce a un menor de doce a dieciséis años?",["De su edad, de su instrucción, de la gravedad y de la complejidad del acto","Únicamente de su edad, valorada el día en que debe tomarse la decisión","Del acuerdo previo de los titulares de la patria potestad"],["La relación entre riesgo y beneficio y el carácter urgente de la situación también cuentan.","Esa capacidad no puede ser nunca rígida: varía según múltiples factores.","La apreciación corresponde al profesional, no a los progenitores."]],
  "227": ["¿Qué puede hacer el médico en caso de conflicto entre un menor de doce a dieciséis años y sus progenitores?",["Seguir la decisión de los progenitores, que prevalece en cualquier caso","Informar al juez para que intervenga el ministerio fiscal o se designe un defensor","Suspender los cuidados hasta que se alcance un acuerdo entre las partes"],["El conflicto justifica precisamente la intervención de un tercero encargado de proteger al menor.","Ese recurso vale también en caso de desacuerdo entre los propios progenitores.","La suspensión de los cuidados puede perjudicar al menor al que se trata de proteger."]],
  "228": ["¿Cómo se decide un acto de riesgo grave para un menor de dieciséis a dieciocho años?",["El menor consiente por sí solo, y los progenitores simplemente se informan después","El profesional decide por sí solo atendiendo al interés superior del menor","Los progenitores o representantes legales consienten por representación"],["Esa modalidad vale para los actos que no implican riesgo grave.","El profesional no sustituye a los titulares de la patria potestad.","La decisión tiene presente el principio de beneficencia para la salud de la persona representada."]],
  "229": ["¿Para cuál de estas situaciones se exige la edad de dieciocho años?",["La participación en una investigación clínica","La interrupción voluntaria del embarazo en una menor de dieciséis años","La prescripción de un anticonceptivo a una adolescente que lo solicita"],["La mayoría de edad se requiere igualmente para la reproducción asistida, el trasplante y la esterilización.","En ese caso solo es necesario el consentimiento de la menor.","El menor puede consentir por sí solo a ese tipo de consulta."]],
  "230": ["¿Cuál es el alcance del consentimiento del menor en el derecho francés?",["Debe obtenerse, y de lo contrario el acto no puede practicarse","Debe buscarse siempre que sea posible, sin primar sobre el de los progenitores","No tiene que buscarse antes de la edad de madurez reconocida"],["La exigencia versa sobre la búsqueda del consentimiento, no sobre su obtención.","La decisión de los titulares de la patria potestad prevalece en definitiva.","El menor tiene derecho a ser informado y a participar en la decisión médica."]],
  "231": ["¿En qué caso se requiere únicamente el consentimiento del menor?",["Cuando tiene más de quince años y vive fuera del hogar familiar","Cuando ejerce una actividad profesional remunerada a tiempo completo","Cuando, roto el vínculo familiar, se beneficia personalmente del seguro de enfermedad"],["La edad y la residencia no bastan: lo que cuenta es el beneficio personal de las prestaciones.","La actividad profesional no conlleva por sí misma esa autonomía.","Su cobertura personal justifica que decida por sí solo sobre los cuidados que le conciernen."]],
  "232": ["¿En qué consiste el derecho de veto que se reconoce al menor?",["Puede oponerse a un acto no necesario para su salud, a pesar del acuerdo parental","Puede rechazar todo acto médico siempre que comprenda su alcance","Puede exigir que se recabe una segunda opinión médica antes del acto"],["Se contemplan la extracción de médula ósea en beneficio de un allegado o la participación en una investigación.","El veto solo versa sobre los actos que no son necesarios para su salud.","El derecho reconocido es el de oponerse, no el de obtener una segunda valoración."]],
  "233": ["¿Quién debe consentir a un acto habitual para el hijo de progenitores separados?",["Los dos titulares de la patria potestad, sin excepción posible","Un solo titular de la patria potestad, que se reputa que actúa con el acuerdo del otro","El progenitor en cuyo domicilio se ha fijado la residencia habitual del menor"],["El acuerdo conjunto solo se exige para los actos no habituales.","Un control de rutina en el pediatra corresponde a esa categoría.","La residencia habitual no determina por sí sola quién puede consentir."]],
  "234": ["¿Qué actos exigen el consentimiento conjunto de los dos progenitores separados?",["Todos los actos realizados al margen del médico habitual del menor","Todos los actos realizados durante el periodo de residencia con el otro progenitor","Los actos no habituales, como una cirugía o un tratamiento de riesgo grave"],["El profesional consultado no cambia la naturaleza habitual o no del acto.","El calendario de residencia no entra en esa distinción.","El carácter inhabitual y la gravedad del riesgo exigen el acuerdo de los dos titulares."]],
  "235": ["¿Qué hacer si el acuerdo de los dos progenitores se demora hasta perjudicar al menor?",["El médico puede actuar con el acuerdo de uno solo de ellos","El médico debe acudir al juez antes de practicar el menor acto","El médico debe esperar el acuerdo escrito del progenitor que ha permanecido en silencio"],["El plazo de recogida no debe causar un retraso perjudicial para el interés del menor.","Acudir al juez corresponde a los progenitores en caso de desacuerdo, y no puede retrasar un cuidado necesario.","Esperar indefinidamente equivaldría a hacer recaer en el menor el desinterés de un progenitor."]],
  "236": ["¿Para qué consultas puede un menor consentir por sí solo, sin que se avise a los progenitores?",["Cualquier consulta de medicina general que solicite por iniciativa propia","Anticoncepción, embarazo o interrupción, cribado anónimo y cuidados ligados a la toxicomanía","Cualquier consulta realizada en un centro público de salud"],["Esa autonomía solo vale para las situaciones limitadamente previstas por la ley.","Si el menor mantiene su oposición a informar a sus progenitores, se hace acompañar de un mayor de edad de su elección.","El lugar de la consulta no abre ningún derecho particular al menor."]],
  "237": ["¿Cómo se decide sobre la salud de un adulto con medidas de protección?",["La persona encargada de su protección decide en toda circunstancia","El médico decide por sí solo atendiendo al interés del adulto protegido","Decide por sí solo en la medida en que su estado lo permite"],["La medida de protección no conlleva por sí misma una pérdida del poder de decidir.","El profesional no sustituye ni al adulto ni a la persona encargada de su protección.","El juez puede prever una asistencia, e incluso una representación, cuando su estado ya no lo permite."]],
  "238": ["¿Cuándo es necesaria la autorización del juez para un adulto con medidas de protección?",["Para una decisión que atente gravemente contra la intimidad de su vida privada","Para todo acto quirúrgico realizado con anestesia general","Para todo ingreso de una duración superior a cuarenta y ocho horas"],["Una esterilización con fines anticonceptivos constituye el ejemplo típico.","La persona encargada de la protección puede consentir a los actos que atentan contra la integridad corporal.","La duración del ingreso no condiciona la intervención del juez."]],
  "239": ["¿Cuál de estas características no define la fase terminal?",["La presencia de síntomas intensos, múltiples, multifactoriales y cambiantes","La imposibilidad de obtener alivio mediante cuidados paliativos adecuados","Un fuerte impacto emocional en el paciente, la familia y el equipo asistencial"],["Esa inestabilidad sintomática forma parte de los elementos fundamentales.","Los elementos establecidos son la enfermedad avanzada e incurable, la ausencia de respuesta al tratamiento y los síntomas múltiples.","La presencia, explícita o no, de la muerte marca al conjunto de los actores."]],
  "240": ["¿Qué esperanza de vida caracteriza la fase terminal?",["Inferior a doce meses","Inferior a tres meses","Inferior a seis meses"],["Ese plazo es demasiado largo para caracterizar la situación descrita.","Ese plazo corresponde a las últimas semanas, y no a la entrada en fase terminal.","Esa referencia acompaña la evolución inexorable hacia la muerte de una enfermedad avanzada e incurable."]],
  "241": ["¿Cómo se aplica el principio de no maleficencia al paciente en el final de la vida?",["Evitar la obstinación terapéutica y practicar la adecuación del esfuerzo terapéutico","Aportar una solución integral a sus problemas físicos, sociales y espirituales","Garantizar un sistema de salud universal que cubra sus necesidades sin discriminación"],["El paciente no debe ser dañado inútilmente con procedimientos desproporcionados o puramente suspensivos.","Esa atención global corresponde al principio de beneficencia.","Esa exigencia de acceso corresponde al principio de justicia."]],
  "242": ["¿Quién puede redactar un documento de instrucciones previas?",["Cualquier persona, incluso menor, siempre que esté consciente","Una persona mayor de edad, capaz y libre, por escrito","Una persona mayor de edad, de forma oral ante dos testigos"],["Se requieren la mayoría de edad y la capacidad para otorgar ese documento.","En él expresa de antemano su voluntad para el caso de que ya no pueda hacerlo personalmente.","Se exige la forma escrita para otorgar las instrucciones."]],
  "243": ["¿Sobre qué pueden versar las instrucciones previas?",["Únicamente la designación de un representante encargado de expresar la voluntad del paciente","El reparto de los bienes del paciente tras su fallecimiento","Los cuidados y tratamientos, el destino del cuerpo o de los órganos y la designación de un representante"],["Su objeto es más amplio y cubre también los cuidados y el destino del cuerpo.","Las disposiciones patrimoniales corresponden al testamento y no a las instrucciones previas.","Ese representante sirve de interlocutor con el equipo para la ejecución de las instrucciones."]],
  "244": ["¿En qué casos no se aplican las instrucciones previas?",["Si son contrarias al orden jurídico, a la lex artis, o a la situación prevista","Si la familia del paciente se opone a su aplicación efectiva","Si se redactaron más de cinco años antes de la situación planteada"],["Siguen siendo además libremente revocables en cualquier momento, por escrito.","La oposición de los allegados no impide la ejecución de las instrucciones.","No va ligada al documento ninguna duración de validez limitada."]],
  "245": ["¿Qué situación da derecho a la ayuda para morir en el derecho español?",["Toda enfermedad crónica que conlleve dependencia para las actividades cotidianas","Un padecimiento grave, crónico e imposibilitante, o una enfermedad grave e incurable","Todo sufrimiento psíquico duradero que los tratamientos no consigan aliviar"],["La dependencia por sí sola no basta: se requiere el sufrimiento intolerable.","Las dos situaciones suponen un sufrimiento constante e intolerable para la persona que lo padece.","Un sufrimiento psicológico aislado no permite por sí solo acceder a ese procedimiento."]],
  "246": ["¿Qué condición de residencia se exige para acceder a la ayuda para morir en España?",["La sola presencia en el territorio en el momento de formular la solicitud","La residencia legal desde al menos cinco años consecutivos","La nacionalidad, la residencia legal o una estancia acreditada de más de doce meses"],["Una presencia puntual no satisface la condición establecida.","La duración exigida es claramente más corta que esa.","Esa condición evita que el procedimiento se solicite desde el extranjero."]],
  "247": ["¿Qué protección se prevé para los profesionales que se niegan a participar en la ayuda para morir?",["Una objeción de conciencia que les permite no tomar parte en el procedimiento","Una autorización previa de su colegio profesional para retirarse","Una dispensa concedida caso por caso por el director del centro"],["Se ejerce sin que el paciente quede abandonado ni privado de sus derechos.","No se requiere ninguna autorización colegial para hacer valer esa objeción.","La objeción es un derecho del profesional, no un favor administrativo."]],
  "248": ["¿Qué verificación se impone el día de la administración del producto letal?",["Un segundo médico debe confirmar por escrito el pronóstico inicialmente establecido","El médico o el enfermero debe verificar que la persona confirma su voluntad","La persona de confianza debe refrendar la solicitud formulada por el paciente"],["La verificación versa sobre la voluntad actual del enfermo, no sobre el pronóstico.","El paciente conserva hasta el final el derecho a renunciar a su solicitud.","No se exige ningún refrendo de un tercero en esa fase."]],
  "249": ["¿Cómo se desarrolla el procedimiento colegiado previsto para la ayuda para morir?",["El médico decide por sí solo tras consultar la historia clínica del paciente","Un comité de ética del centro emite un dictamen vinculante previo","Un colegio pluriprofesional reúne al médico, a un especialista y a un profesional del tratamiento"],["La decisión va precedida de una deliberación en la que participan varios profesionales.","El procedimiento se apoya en un colegio constituido para el caso, no en el comité de ética.","Pueden convocarse otros profesionales, y puede recabarse la opinión de la persona de confianza."]],
  "250": ["¿Qué plazos enmarcan la decisión relativa a la ayuda para morir?",["Decisión motivada en quince días y después reflexión de al menos dos días antes de la confirmación","Decisión inmediata tras la reunión del colegio, sin plazo de reflexión","Decisión en tres meses, acompañada de un plazo de reflexión de un mes"],["Esos plazos garantizan a la vez el examen serio de la solicitud y la libertad del enfermo.","Se reserva expresamente un tiempo de reflexión antes de la confirmación de la solicitud.","Los plazos previstos son claramente más cortos que esos."]],
  "251": ["¿Cómo ha evolucionado la naturaleza del secreto desde la tradición hipocrática?",["De un deber del buen profesional a un derecho del paciente a la confidencialidad","De una obligación moral a una simple recomendación de buena práctica","De una regla propia de los médicos a una regla propia de los centros"],["Antaño el profesional decidía lo que debía permanecer en secreto; hoy el control pertenece al paciente.","Su violación constituye al contrario un delito castigado por el código penal.","La obligación recae sobre cada profesional, no solo sobre la institución."]],
  "252": ["¿Qué es la confidencialidad?",["La obligación profesional de callar lo que se conoce en el ejercicio del oficio","El derecho del paciente a exigir que sus datos íntimos no se revelen ni se utilicen","La limitación técnica de los accesos informáticos a la historia del paciente"],["Esa obligación define el secreto profesional, más específico que el deber de confidencialidad.","Esa exigencia se dirige a todos los que han tenido conocimiento de esos datos, sin su autorización expresa.","Las medidas técnicas sirven a la confidencialidad sin definirla."]],
  "253": ["¿Sobre qué versa la obligación de secreto del fisioterapeuta?",["Únicamente los datos médicos consignados en la historia del paciente","Únicamente la información que el paciente ha designado expresamente como secreta","Toda la información sobre la salud, la intimidad, el cuerpo y las relaciones sociales"],["La obligación desborda ampliamente el contenido de la historia.","El secreto se aplica de oficio, sin designación previa por el paciente.","Abarca incluso el sentimiento del paciente respecto a su enfermedad."]],
  "254": ["¿Cuánto dura la obligación de secreto profesional?",["Toda la vida del profesional, y el fallecimiento del paciente no le libera de ella","Hasta el final de la atención del paciente por el profesional","Hasta el fallecimiento del paciente, que pone fin a la protección de sus datos"],["Se mantiene incluso después del final de la relación profesional con la persona atendida.","Persiste mucho más allá de la relación asistencial.","El fallecimiento no autoriza a hacer públicas las informaciones recogidas."]],
  "255": ["¿Cómo se califican los datos personales de salud?",["Como datos ordinarios sujetos al régimen común de los ficheros","Como datos sensibles, que disfrutan de una protección particular","Como datos públicos desde el momento en que se anonimizan"],["Su carácter sensible les otorga un régimen reforzado.","Esa protección figura en los códigos de salud pública, de seguridad social y penal.","La anonimización es una medida de protección, no un cambio de calificación."]],
  "256": ["¿Cuál es la particularidad del inicio del procedimiento penal en el derecho francés?",["Es indispensable una denuncia de la persona perjudicada o de su representante","Solo el colegio profesional puede acudir al órgano judicial competente","El ministerio fiscal puede perseguir de oficio, incluso sin denuncia del paciente"],["Esa exigencia de denuncia previa caracteriza al derecho español.","El colegio puede iniciar un procedimiento disciplinario, distinto de la acción penal.","La violación del secreto profesional es allí una infracción de interés general."]],
  "257": ["¿Qué efecto produce el perdón de la víctima en el derecho francés?",["Ninguno: la retirada de la denuncia no detiene el procedimiento iniciado","Pone fin a la acción penal iniciada contra el profesional","Transforma el procedimiento penal en procedimiento disciplinario"],["El juez puede condenar al profesional a pesar del perdón de su paciente.","Ese efecto extintivo es el que prevé el derecho español.","Los dos procedimientos son independientes y pueden acumularse."]],
  "258": ["¿Qué sanciones pueden añadirse a la pena prevista por la violación del secreto?",["Únicamente la obligación de indemnizar al paciente por el perjuicio sufrido","La prohibición de ejercer la actividad profesional y un procedimiento disciplinario interno","La retirada definitiva de la historia clínica del centro implicado"],["La indemnización corresponde a la responsabilidad civil y no resume las sanciones en que se incurre.","Esas medidas se acumulan con la prisión y la multa en que se incurre.","No se prevé ninguna medida de ese tipo a título de sanción."]],
  "259": ["¿Quién puede acceder a la historia clínica de un paciente?",["El conjunto del personal del centro donde se atiende al paciente","Los allegados del paciente siempre que acrediten un vínculo familiar","Los profesionales cuya función lo exija, sin poder divulgar su contenido"],["El acceso se limita a lo necesario para el ejercicio de las funciones.","El acceso de terceros supone el consentimiento del paciente o una resolución judicial.","La extensión del acceso depende de la función que cada uno ejerce efectivamente."]],
  "260": ["¿A qué están sujetos los trabajadores no asistenciales que acceden a la historia?",["Al deber de confidencialidad, al no estar obligados por el secreto profesional","A ninguna obligación particular, al no ser profesionales sanitarios","Únicamente al reglamento interno del centro que los emplea"],["La distinción depende de su condición, pero la obligación de no divulgar nada se mantiene.","Todo trabajador que accede a la historia queda obligado, por un título u otro.","Su obligación excede el marco disciplinario interno."]],
  "261": ["¿Cómo se controla el acceso a la historia clínica informatizada?",["Cada consulta requiere la autorización previa del supervisor asistencial","Cada consulta deja un registro que indica quién, cuándo y por qué","Cada consulta se notifica al paciente afectado por vía electrónica"],["El control es a posteriori, mediante la trazabilidad, y no por autorización previa.","Ese registro permite detectar posibles accesos indebidos o no autorizados.","No se prevé ninguna notificación sistemática al paciente."]],
  "262": ["¿Qué consecuencias puede conllevar la divulgación no autorizada de una historia?",["Una simple advertencia inscrita en el expediente profesional del trabajador infractor","Una obligación de reparación limitada al perjuicio material demostrado","Sanciones administrativas, denuncia del paciente con indemnización y pena penal si el caso es grave"],["La gravedad del atentado exige consecuencias mucho más severas.","La indemnización cubre los daños y perjuicios sufridos, más allá del solo perjuicio material.","La divulgación ilegal puede calificarse de delito de revelación de secretos."]],
  "263": ["¿Qué es el secreto profesional compartido?",["La extensión de la información a otros profesionales en beneficio exclusivo del paciente","La posibilidad de informar a la familia del paciente de su estado de salud","La puesta en común de las historias entre centros de un mismo territorio"],["Solo deben transmitirse los datos esenciales para la mejora de la asistencia.","La información a los allegados depende de la autorización del paciente, no del secreto compartido.","El reparto se dirige al equipo que atiende al paciente, no a instituciones enteras."]],
  "264": ["¿Qué hay que prever cuando se consulta a un colega sobre una situación clínica?",["Recoger previamente el consentimiento escrito del paciente","Ocultar en todos los casos la identidad del paciente afectado","Abstenerse de toda consulta ajena al equipo asistencial"],["El secreto compartido entre profesionales no exige un escrito previo.","La consulta sigue siendo posible en beneficio del restablecimiento, con esa reserva.","La discusión entre profesionales se admite cuando sirve al paciente."]],
  "265": ["¿Cuál de estos intervinientes no está sujeto al secreto?",["Los estudiantes en prácticas, que todavía no son profesionales","Las secretarías médicas, que no participan en la asistencia","Ninguno: estudiantes en prácticas, secretarías y laboratorios están todos obligados"],["Su condición de estudiante no les exime de la obligación de secreto.","Están expresamente sujetas a esa obligación.","La obligación se extiende a los auxiliares, a las trabajadoras sociales y a los técnicos de farmacia."]],
  "266": ["¿Cuánto dura la obligación de secreto para los no asistenciales que colaboran?",["Indefinidamente","Durante la vigencia de su contrato con el centro","Durante cinco años tras el final de la atención del paciente"],["La extensión del secreto a los colaboradores no comporta ningún límite de duración.","El fin del contrato no libera de la obligación contraída.","No se prevé ninguna duración de ese tipo."]],
  "267": ["¿Qué conviene preguntar al paciente al comienzo de la relación clínica?",["Si acepta que su historia sea consultada por el equipo asistencial","Si desea ser informado y a quién más desea que se informe","Si consiente que sus datos se utilicen con fines de investigación"],["El acceso del equipo se deriva de la atención, sin autorización específica.","Esa pregunta fija de entrada el perímetro de lo que podrá compartirse.","Esa pregunta se plantea ante un proyecto de investigación, y no al abrir la relación."]],
  "268": ["¿Qué precaución se impone para las acciones sin finalidad asistencial, como una grabación?",["Informar al paciente sin tener que recoger su acuerdo formal","Obtener el acuerdo del responsable del servicio, que compromete al centro","Obtener una autorización explícita del paciente"],["La simple información no basta para una finalidad ajena a la asistencia.","El acuerdo jerárquico no sustituye al de la persona afectada.","Esa exigencia vale también para la presencia de estudiantes con fines docentes."]],
  "269": ["¿Cómo se viola el deber de confidencialidad en la mayoría de los casos?",["Por acciones inconscientes, nacidas de la familiaridad, la rutina y la falta de reflexión","Por divulgaciones intencionadas a terceros ajenos al equipo","Por fallos técnicos de los sistemas informáticos hospitalarios"],["Comentar un paciente en un ascensor o dejar una sesión abierta son ejemplos de ello.","Los incumplimientos deliberados son minoritarios frente a las negligencias ordinarias.","Las vulneraciones dependen ante todo de las conductas, no de las herramientas."]],
  "270": ["¿En cuál de estos casos es posible levantar el secreto?",["Cuando la familia reclama explicaciones sobre el estado del paciente","En caso de infracción cometida contra un menor o una persona vulnerable","Cuando el empleador del paciente solicita información sobre su baja"],["La petición de los allegados no constituye nunca una causa de levantamiento del secreto.","La vulnerabilidad puede deberse a la edad, al embarazo, a la enfermedad o a una deficiencia.","El empleador no tiene ningún derecho de acceso a los datos de salud de su trabajador."]],
  "271": ["¿Qué actitud se impone cuando el profesional debe romper el secreto?",["Comunicar la historia íntegra para evitar toda interpretación errónea","Informar previamente al colegio profesional de la actuación emprendida","Reducir al mínimo la información revelada y el número de personas que la reciben"],["Solo puede revelarse lo estrictamente necesario para el objetivo predominante.","No se exige ninguna formalidad colegial previa.","Su primera preocupación moral debe seguir siendo la seguridad del paciente; la ruptura es una medida desesperada."]],
  "272": ["¿Cuál de estas situaciones constituye una excepción al secreto profesional?",["La comunicación de las enfermedades de declaración obligatoria a las autoridades sanitarias","La petición de una compañía de seguros que instruye un expediente de siniestro","La petición de un colega curioso por la evolución de un caso interesante"],["Figuran también el peritaje, la sospecha de maltrato y la obligación de testificar en juicio.","La aseguradora no tiene acceso a los datos cubiertos por el secreto.","La curiosidad profesional no justifica ninguna transmisión de información."]],
  "273": ["¿Qué permite la necesidad de prevenir delitos graves?",["Comunicar toda conducta del paciente juzgada moralmente reprobable","Divulgar la información confiada si eso impide la comisión de futuros delitos","Transmitir la historia completa a los servicios de investigación que la reclaman"],["La facultad se limita estrictamente a la prevención de infracciones graves.","Esa facultad se dirige esencialmente a las infracciones graves.","Solo puede revelarse lo necesario para la prevención."]],
  "274": ["¿Qué criterios permiten resolver un conflicto entre el secreto y otro deber?",["La antigüedad de la relación con el paciente y la gravedad de su patología","El número de personas expuestas y el coste de la atención","La magnitud del daño y la probabilidad de que se produzca"],["Ni la duración de la relación ni la gravedad de la enfermedad son los criterios establecidos.","El coste no entra en la ponderación entre secreto y protección de terceros.","Cada situación debe además analizarse individualmente."]],
  "275": ["Ante un paciente muy contagioso que se niega a avisar a sus compañeros de piso, ¿qué hacer?",["Informarle de que el profesional los avisará, limitando la información al riesgo asumido","Respetar su negativa, pues el secreto prima sobre la protección de terceros","Comunicar el conjunto de la historia a las personas expuestas al riesgo"],["Sería injustificado revelar otros elementos de la historia que no les exponen a ningún riesgo.","El daño mayor y altamente probable justifica aquí el levantamiento del secreto.","Solo puede transmitirse el mínimo de información necesario para evitar el daño."]],
  "276": ["¿Qué hacer cuando la magnitud y la probabilidad del perjuicio son ambas bajas?",["Informar a los terceros afectados por precaución, pues la duda favorece la seguridad","Mantener el secreto: romperlo sería un error del profesional","Acudir sistemáticamente a la autoridad judicial para obtener una instrucción"],["Romper la confidencialidad sin necesidad constituye una falta.","Esa es la configuración en la que la confidencialidad debe prevalecer con claridad.","Acudir al juez no es la respuesta esperada en esa situación."]],
  "277": ["¿Qué hacer en caso de duda sobre la decisión que hay que adoptar?",["Resolver en favor del secreto, que constituye la regla de principio","Resolver en favor de la información, pues la seguridad prima siempre","Pedir el dictamen de un comité de ética asistencial"],["La duda exige una deliberación, no la aplicación mecánica de una presunción.","Ninguno de los dos valores prevalece automáticamente sobre el otro.","Las situaciones intermedias exigen una evaluación cuidadosa de las circunstancias y de las consecuencias."]],
  "278": ["¿Qué impone la preeminencia del derecho a la integridad física?",["Comunicar al tribunal los pacientes atendidos por agresión o los casos sospechosos de abuso","Recoger el acuerdo de la víctima antes de toda comunicación a la justicia","Limitar la comunicación únicamente a las víctimas menores o vulnerables"],["Esa obligación se impone incluso si la víctima no es favorable a ella.","La comunicación se impone con independencia de la voluntad de la persona afectada.","La obligación atañe a las agresiones y a los abusos sospechados, sin esa restricción."]],
  "279": ["¿Cuáles son los tres objetivos del reglamento general de protección de datos?",["Reforzar los derechos, responsabilizar a los actores y dar credibilidad a la regulación","Armonizar las sanciones, centralizar los ficheros y simplificar los trámites","Prohibir las transferencias, limitar la duración e imponer el cifrado de los datos"],["La cooperación reforzada entre autoridades de protección sostiene ese último objetivo.","El texto armoniza las reglas de tratamiento, no la centralización de los ficheros.","Esas medidas técnicas se derivan del texto sin constituir sus objetivos."]],
  "280": ["¿Quién es el responsable del tratamiento de los datos?",["Quien trata los datos por cuenta de otro organismo","Quien determina los fines y los medios del tratamiento","Aquel cuyos datos personales son objeto del tratamiento"],["Esa definición es la del encargado del tratamiento de los datos.","Puede tratarse de una persona física o jurídica, de una autoridad pública o de un organismo.","La persona afectada es el sujeto de los datos, no el responsable."]],
  "281": ["¿Qué debe poder demostrar el responsable cuando el tratamiento se basa en el consentimiento?",["Que el tratamiento es necesario para cumplir una misión de interés público","Que los datos se han recogido directamente de la persona","Que la persona afectada ha consentido efectivamente al tratamiento"],["Esa necesidad constituye otra base legal, distinta del consentimiento.","El origen de los datos no es lo que fundamenta la licitud del tratamiento.","Esta conserva además el derecho a retirar su consentimiento en cualquier momento."]],
  "282": ["¿A partir de qué edad puede un menor consentir por sí solo al tratamiento de sus datos?",["Quince años en Francia, catorce años en España","Dieciséis años en Francia, quince años en España","Dieciocho años en los dos países, sin excepción posible"],["Por debajo, el consentimiento debe darse conjuntamente con los titulares de la patria potestad.","Los umbrales establecidos son un año inferiores a esos.","La mayoría de edad no se exige para ese tipo de consentimiento."]],
  "283": ["¿Cómo debe redactar el responsable la información destinada a un menor?",["En los mismos términos que para un adulto, para garantizar la exactitud","En términos claros y sencillos, fácilmente comprensibles para él","A través de sus representantes legales, que se la transmiten"],["Una información no comprendida no permite un consentimiento válido.","La adaptación al destinatario condiciona la validez de su consentimiento.","La información debe dirigirse a él directamente y de forma inteligible."]],
  "284": ["¿Qué datos son objeto de una prohibición de principio de tratamiento?",["Únicamente los datos de salud y los datos genéticos de las personas","Los datos que permiten localizar a una persona o identificar a sus allegados","Origen étnico, opiniones, convicciones, salud, genética, biometría y vida sexual"],["La prohibición cubre un conjunto mucho más amplio de categorías sensibles.","Esos datos no figuran entre las categorías especiales enumeradas.","La afiliación sindical figura igualmente entre esas categorías especiales."]],
  "285": ["¿Cuál de estas circunstancias no levanta la prohibición de tratar datos sensibles?",["El interés comercial del responsable en dirigirse mejor a su clientela","La necesidad de proteger los intereses vitales de una persona incapaz de consentir","El hecho de que la persona haya hecho manifiestamente públicos sus datos"],["Las excepciones dependen del consentimiento explícito, de los intereses vitales o del interés público esencial.","Esa excepción atañe a la persona que no puede consentir física o jurídicamente.","Esa publicidad voluntaria figura entre las circunstancias que levantan la prohibición."]],
  "286": ["¿Con qué condición pueden tratarse los datos de salud con fines asistenciales?",["Que lo autorice el director del centro donde se atiende al paciente","Que lo realice un profesional sujeto al secreto, o bajo su responsabilidad","Que el tratamiento verse exclusivamente sobre datos anonimizados"],["La autorización administrativa no suple la garantía del secreto profesional.","Se contemplan la medicina preventiva, el diagnóstico, la asistencia y la gestión de los servicios de salud.","La anonimización volvería imposible la atención individual del paciente."]],
  "287": ["¿Cuál de estos derechos no se reconoce a la persona afectada?",["El derecho a no ser objeto de una decisión individual automatizada","El derecho a la limitación del tratamiento de sus datos personales","El derecho a obtener la destrucción del sistema informático del responsable"],["Ese derecho figura expresamente entre los reconocidos a la persona afectada.","Esa limitación forma parte de los derechos que la persona puede ejercer.","Los derechos previstos son el acceso, la rectificación, la supresión, la limitación, la portabilidad y la oposición."]],
  "288": ["¿Qué puede obtener la persona en virtud de su derecho de acceso?",["La confirmación del tratamiento, sus fines, los destinatarios y una copia de los datos","Únicamente la confirmación de que se tratan datos que le conciernen","La identidad de cada trabajador que ha consultado su historia y la fecha de consulta"],["Conoce también el plazo de conservación y la existencia eventual de decisiones automatizadas.","El derecho de acceso es mucho más amplio que esa simple confirmación.","La trazabilidad de los accesos corresponde a la historia clínica, no al derecho de acceso previsto aquí."]],
  "289": ["¿Qué abarca el derecho de rectificación?",["Hacer suprimir los datos que han dejado de ser útiles para el fin perseguido","Hacer corregir los datos inexactos y completar los que están incompletos","Hacer suspender provisionalmente el tratamiento durante una verificación"],["Esa supresión corresponde al derecho de supresión.","Ambas vertientes, corrección y complemento, están expresamente previstas.","Esa suspensión corresponde al derecho a la limitación del tratamiento."]],
  "290": ["¿En cuál de estos casos debe concederse la supresión de los datos?",["Cuando la persona estima que la conservación de los datos le perjudica","Cuando el responsable cambia de actividad o de forma jurídica","Cuando los datos ya no son necesarios para los fines perseguidos"],["El perjuicio percibido no es en sí una causa de supresión.","El cambio de estructura no abre ningún derecho de supresión.","La supresión se impone también en caso de retirada del consentimiento o de tratamiento ilícito."]],
  "291": ["¿En cuál de estos casos no se suprimirán los datos a pesar de la solicitud?",["Cuando el tratamiento es necesario para la defensa de un derecho en juicio","Cuando la supresión representaría un coste importante para el responsable","Cuando los datos se han transmitido a otro responsable del tratamiento"],["El ejercicio de la libertad de expresión y los motivos de salud pública también impiden la supresión.","El coste de la operación no constituye un motivo de denegación.","La transmisión a un tercero no impide el ejercicio del derecho."]],
  "292": ["¿En qué condiciones se ejerce el derecho a la portabilidad?",["El tratamiento se basa en una obligación legal que pesa sobre el responsable","El tratamiento se basa en el consentimiento y se efectúa por medios automatizados","El tratamiento lo lleva a cabo un organismo público o parapúblico"],["Ese fundamento no abre el derecho a la portabilidad.","Los datos se reciben entonces en un formato estructurado y legible por máquina.","El derecho no se aplica al tratamiento que corresponde a una misión de interés público."]],
  "293": ["¿Qué puede pedir la persona que ejerce su derecho a la portabilidad?",["Que sus datos se supriman de inmediato en el responsable de origen","Que sus datos se hagan públicos en un formato abierto","Que sus datos pasen directamente de un responsable a otro"],["La supresión constituye un derecho distinto, que se ejerce por separado.","La portabilidad organiza una transferencia, no una publicación.","Esa transmisión directa es posible cuando resulta técnicamente realizable."]],
  "294": ["¿En qué caso puede el responsable continuar el tratamiento a pesar de una oposición?",["Si demuestra motivos legítimos e imperiosos que prevalecen sobre esos derechos","Si estima que la oposición formulada no está suficientemente motivada por la persona","Si ya ha asumido gastos importantes para poner en marcha el tratamiento"],["La defensa de un derecho en juicio permite igualmente mantener el tratamiento.","La apreciación del responsable sobre la motivación no basta para descartar la oposición.","Los gastos asumidos no constituyen un motivo legítimo imperioso."]],
  "295": ["¿Qué particularidad presenta la oposición en materia de marketing directo?",["Supone que la persona acredite una situación que le es particular","Se ejerce en cualquier momento y se señala desde la primera comunicación","Solo puede ejercerse una vez por año natural"],["Esa exigencia vale para la oposición ordinaria, no para el marketing directo.","Ese derecho se presenta con claridad, con independencia de cualquier otra información.","No se prevé ninguna limitación de frecuencia para ese derecho."]],
  "296": ["¿Cuándo sigue siendo posible una decisión enteramente automatizada?",["Si la ha validado previamente el delegado de protección de datos designado","Si la persona afectada no ha expresado oposición en el plazo señalado","Si es necesaria para un contrato, está autorizada por la ley o se ha consentido expresamente"],["La intervención del delegado no legitima por sí sola una decisión así.","El silencio de la persona no equivale a la aceptación de una decisión automatizada.","Deben entonces proteger los derechos e intereses de la persona unas medidas apropiadas."]],
  "297": ["¿Sobre qué datos no puede en principio basarse una decisión automatizada?",["Sobre las categorías especiales de datos de carácter personal","Sobre los datos obtenidos de terceros en lugar de la propia persona","Sobre los datos conservados desde hace más de cinco años por el responsable"],["Salvo consentimiento o interés público esencial acompañado de medidas de protección apropiadas.","El origen de los datos no es el criterio de prohibición establecido.","La antigüedad de los datos no entra en esa prohibición."]],
  "298": ["¿Quién puede solicitar el acceso a los datos de una persona fallecida?",["Cualquier persona que acredite un interés legítimo en conocer esos datos","Las personas vinculadas por razones familiares o de hecho, y los herederos","Únicamente el notario encargado de la tramitación de la herencia del fallecido"],["El acceso se reserva a los allegados y a los herederos, no a cualquier interesado.","Esa facultad cesa si el fallecido la había prohibido expresamente o si la ley se opone a ella.","El notario no está investido de esa prerrogativa."]],
  "299": ["¿Quién puede ejercer esos derechos en caso de fallecimiento de un menor?",["Únicamente sus representantes legales, con exclusión de cualquier otra persona","El juez de familia a instancia de uno de los titulares de la patria potestad","Sus representantes legales o el ministerio fiscal, de oficio o a instancia de parte"],["El ministerio fiscal dispone igualmente de esa facultad.","Acudir al juez no es la vía prevista en ese caso.","El ministerio fiscal puede actuar a instancia de cualquier persona interesada."]],
  "300": ["¿Cuál es el alcance de la obligación de confidencialidad en materia de datos?",["Recae sobre todas las personas que intervienen en alguna fase del tratamiento","Solo recae sobre el responsable del tratamiento y su encargado","Cesa en cuanto termina la relación con el responsable del tratamiento"],["Para los profesionales sanitarios se añade al deber de secreto profesional que ya les incumbe.","Se extiende a toda persona que interviene en el tratamiento, en cualquier fase.","Esas obligaciones siguen siendo aplicables incluso después del fin de la relación."]],
  "301": ["¿Con qué fin puede ponerse en marcha un sistema de videovigilancia?",["Evaluar la calidad del servicio prestado a los usuarios del centro","Preservar la seguridad de las personas, de los bienes y de las instalaciones","Constituir un historial de afluencia con fines estadísticos"],["La evaluación de la calidad no es una finalidad admitida para ese tratamiento.","Solo pueden captarse las imágenes de la vía pública indispensables para ese fin.","Las finalidades estadísticas no justifican una captación de imágenes."]],
  "302": ["¿En qué plazo deben suprimirse las imágenes de videovigilancia?",["En un plazo máximo de setenta y dos horas tras la captación","En un plazo máximo de seis meses desde la captación","En un plazo máximo de un mes desde su captación"],["Ese plazo es el de la puesta a disposición de las imágenes a la autoridad.","Ese plazo excede ampliamente el previsto.","Solo se conservan más tiempo para probar una infracción."]],
  "303": ["¿Dónde está prohibida la instalación de dispositivos de videovigilancia?",["En los lugares de descanso o de ocio: vestuarios, aseos, comedores","En los locales abiertos al público de la empresa o del centro","En los despachos individuales asignados a los directivos de la empresa"],["Esa prohibición protege la vida privada de los trabajadores en su lugar de trabajo.","Esos espacios pueden al contrario someterse a vigilancia por motivos de seguridad.","Ninguna prohibición específica atañe a esos espacios de trabajo."]],
  "304": ["¿Con qué condición se autoriza la grabación sonora en el lugar de trabajo?",["Cuando los trabajadores han sido informados previamente de la medida","Cuando los riesgos para la seguridad derivados de la actividad son importantes","Cuando el empleador persigue un objetivo de control de la productividad"],["La información previa es necesaria, pero no basta para el sonido.","Esa exigencia es más estricta que la que se aplica a la imagen.","El control de la productividad no justifica una grabación sonora."]],
  "305": ["¿Qué debe hacer un responsable al que se pide que cese las comunicaciones comerciales?",["Suprimir la totalidad de los datos que posee sobre esa persona","Transmitir la solicitud a la autoridad de protección de datos","Señalarle la existencia de los sistemas de exclusión publicitaria"],["La solicitud versa sobre la prospección, no sobre la supresión de todos los datos.","No se requiere ninguna transmisión a la autoridad en ese caso.","Quienes practican el marketing directo deben consultar esos sistemas previamente."]],
  "306": ["¿Quién debe designar un delegado de protección de datos?",["Los centros médicos legalmente obligados a conservar las historias de los pacientes","Todo profesional sanitario que conserve historias, incluso en ejercicio aislado","Únicamente los centros públicos de salud y sus agrupaciones"],["Los profesionales que ejercen a título individual quedan expresamente exentos.","El ejercicio a título individual constituye precisamente una exención.","La obligación no depende del carácter público o privado de la estructura."]],
  "307": ["¿Con qué fin puede el empleador acceder a los contenidos de las herramientas digitales profesionales?",["Para evaluar la carga de trabajo real de cada uno de los trabajadores del servicio","Para verificar el cumplimiento de las obligaciones y garantizar la integridad de los dispositivos","Para recabar elementos con vistas a un posible procedimiento disciplinario"],["La evaluación de la carga no es una finalidad reconocida para ese acceso.","Ese doble objetivo delimita estrictamente la extensión del acceso autorizado.","La finalidad disciplinaria no es la que autoriza el texto."]],
  "308": ["¿Cuándo pueden realizarse estudios científicos sin el consentimiento de las personas?",["Siempre que el estudio esté aprobado por un comité de protección de las personas","Siempre que los resultados no se publiquen de forma nominativa","Por las autoridades de salud pública, en casos de importancia y gravedad excepcionales"],["La aprobación del comité no exime por sí sola del consentimiento.","La ausencia de publicación nominativa no suple el consentimiento.","Esa excepción atañe a las situaciones críticas para la salud de la población."]],
  "309": ["¿Con qué condición es lícita la reutilización de datos para una nueva investigación?",["Cuando la nueva finalidad se vincula científicamente al estudio inicial","Cuando los datos se recogieron hace más de cinco años cumplidos","Cuando el nuevo equipo de investigación pertenece al mismo centro"],["El consentimiento obtenido para una finalidad específica cubre entonces esa prolongación.","La antigüedad de los datos no fundamenta ninguna licitud particular.","La pertenencia institucional no es el criterio establecido."]],
  "310": ["¿Qué exige el uso de datos pseudonimizados en investigación en salud?",["Una autorización previa expedida por la autoridad nacional de protección de datos","Una separación técnica entre el equipo de investigación y los titulares de la clave","Una anonimización completa que vuelva imposible toda reidentificación"],["No se exige ninguna autorización previa de ese tipo.","Los investigadores deben comprometerse a no llevar a cabo ninguna actividad de reidentificación.","La pseudonimización se distingue precisamente de la anonimización irreversible."]],
  "311": ["¿Cuándo es posible la reidentificación de datos pseudonimizados?",["Cuando el equipo de investigación lo solicita de forma motivada al promotor","Al término del estudio, para informar a los participantes de sus resultados","En caso de peligro real para la seguridad o la salud de una persona o de un grupo"],["La solicitud del investigador no basta para levantar la pseudonimización.","La devolución de los resultados no justifica en sí una reidentificación.","Lo es también cuando resulta necesaria para garantizar una asistencia adecuada."]],
  "312": ["¿Qué protección particular rodea la imagen de un menor en los medios?",["Un uso que atente contra su honor sigue siendo ilegítimo, incluso con el acuerdo de los progenitores","El uso sigue siendo libre siempre que los representantes legales hayan consentido","El uso está prohibido en toda circunstancia hasta la mayoría de edad del menor"],["El consentimiento del menor o de sus representantes no puede validar un atentado así.","El acuerdo parental no cubre un uso contrario a los intereses del menor.","La prohibición atañe a los usos atentatorios, no a toda difusión de imagen."]],
  "313": ["¿Cómo se define la lex artis?",["El conjunto de las reglas, escritas o no, reconocidas por los expertos del ámbito","El conjunto de los textos legales que encuadran el ejercicio de las profesiones sanitarias","El conjunto de las recomendaciones emitidas por las sociedades científicas del ámbito"],["Su respeto constituye una obligación implícita del ejercicio de una profesión.","Esas reglas pueden ser no escritas y no se confunden con la ley.","Esas recomendaciones forman parte de ella sin agotar la noción."]],
  "314": ["¿Qué es la mala praxis?",["Un resultado terapéutico inferior al que esperaba el paciente","Una conducta negligente o contraria a los deberes propios de la profesión","Un acto realizado fuera del ámbito de competencia reglamentaria del oficio"],["La asistencia es una obligación de medios: la ausencia de resultado no es culposa.","Atañe también al desconocimiento de la regulación legal aplicable.","Ese ejercicio ilegal corresponde al intrusismo profesional."]],
  "315": ["¿Cuál es el alcance de la obligación que pesa sobre el profesional sanitario?",["Garantizar la curación del paciente siempre que el diagnóstico sea exacto","Emplear sistemáticamente la técnica más reciente disponible","Ejercer según las buenas prácticas y con los medios necesarios"],["El resultado no puede garantizarse: solo se debe la aplicación de los medios.","La novedad de una técnica no obliga a emplearla.","No está obligado a obtener un resultado determinado, salvo compromiso contractual en ese sentido."]],
  "316": ["¿Cuál de estos acontecimientos exonera al profesional de su responsabilidad?",["La fuerza mayor, acontecimiento exterior e independiente de su voluntad","La ausencia de resultado a pesar de una atención conforme a las reglas","La sobrecarga de trabajo que impone la organización del servicio"],["Caso fortuito, riesgo asumido y culpa exclusiva de la víctima producen el mismo efecto.","La ausencia de resultado no es una culpa: la exoneración no se plantea por tanto.","Las restricciones organizativas no exoneran de la diligencia profesional."]],
  "317": ["¿Qué es el caso fortuito en materia de responsabilidad?",["Un acontecimiento exterior e independiente de la voluntad del profesional","Un acontecimiento que se produce en el marco de los riesgos ligados a la actividad sanitaria","Un incumplimiento del paciente de las prescripciones que se le han dado"],["Esa definición es la de la fuerza mayor.","Se distingue de la fuerza mayor, que es exterior a la propia actividad.","Ese incumplimiento constituye la culpa exclusiva de la víctima."]],
  "318": ["¿Qué abarca la culpa exclusiva de la víctima?",["El error del paciente al describir sus propios síntomas","La negativa del paciente a consentir al acto que se le proponía","El incumplimiento por el paciente de las prescripciones generales y específicas"],["Una descripción imperfecta no se asimila a un incumplimiento culposo.","La negativa informada es el ejercicio de un derecho, no una culpa.","La firma de un alta voluntaria es un ejemplo exoneratorio de ello."]],
  "319": ["¿Qué distingue la acción civil de la acción penal?",["Una busca una indemnización, y la otra una condena por un delito","Una atañe a los asalariados, y la otra a los profesionales que ejercen por cuenta propia","Una la ejerce el colegio, y la otra la persona perjudicada"],["La primera se presenta ante la jurisdicción civil, y la segunda en el marco de un procedimiento penal.","La condición del profesional no determina la naturaleza de la acción.","El colegio tramita un procedimiento disciplinario, distinto de esas dos acciones."]],
  "320": ["¿Qué es la negligencia en el sentido de la responsabilidad civil?",["El hecho de no poseer los conocimientos necesarios para actuar","El hecho de no aplicar los conocimientos y competencias de los que se dispone","El hecho de no informar al paciente de los riesgos de la intervención"],["Ese defecto de conocimientos define la incompetencia.","Constituye un incumplimiento de la obligación de diligencia profesional.","El defecto de información es un incumplimiento distinto de la negligencia técnica."]],
  "321": ["¿Cuál es el elemento constitutivo de toda responsabilidad?",["La culpa cometida por el profesional","El nexo de causalidad entre el acto y sus consecuencias","El perjuicio causado"],["La culpa es necesaria, pero no basta sin perjuicio.","Ese nexo une la culpa al perjuicio, que sigue siendo el elemento primero.","Sin daño no puede comprometerse ninguna responsabilidad, aunque haya culpa."]],
  "322": ["¿Cuál de estos perjuicios es de naturaleza patrimonial?",["El lucro cesante derivado del beneficio no percibido por el paciente","El perjuicio corporal derivado del atentado contra la integridad física","El perjuicio moral que experimenta el paciente o sus allegados"],["El daño emergente, sufrido por el patrimonio, corresponde a la misma categoría.","El daño corporal pertenece a los perjuicios no patrimoniales.","El perjuicio moral es igualmente de naturaleza no patrimonial."]],
  "323": ["¿A quién incumbe la prueba del nexo de causalidad?",["Al profesional, que debe demostrar la ausencia de nexo con el daño","Al paciente, que debe establecerlo para comprometer la responsabilidad","A la aseguradora, que instruye la solicitud de indemnización del paciente"],["La carga de la prueba recae sobre quien reclama la reparación.","El nexo une el acto o la omisión del profesional al perjuicio sufrido.","La aseguradora interviene en la fase de cobertura, no en la de la prueba."]],
  "324": ["¿Qué significa la solidaridad en materia de responsabilidad?",["El reparto de la indemnización entre el profesional y su aseguradora","La obligación de auxilio mutuo entre colegas que ejercen en un mismo servicio","La responsabilidad de varios agentes en la producción de un mismo perjuicio"],["Ese reparto corresponde al contrato de seguro y no a la noción jurídica señalada.","Ese auxilio mutuo corresponde a la deontología, no al régimen de la responsabilidad.","La indemnización reclamada puede entonces exigirse a cada uno de ellos."]],
  "325": ["¿Cuándo es contractual la relación entre el paciente y el profesional?",["Cuando el paciente recurre a sus servicios y existe un contrato","Cuando el profesional ejerce por cuenta propia en lugar de como asalariado","Cuando el acto se realiza en un centro sanitario privado"],["En su defecto, el profesional sigue obligado a actuar conforme a la ley y a la tradición asistencial.","La modalidad de ejercicio no determina por sí sola la naturaleza del vínculo.","El carácter privado del centro no crea por sí mismo un contrato."]],
  "326": ["¿Cuál es el plazo de prescripción de la responsabilidad contractual?",["Un año desde el conocimiento del daño","Cinco años","Diez años desde la estabilización del daño"],["Ese plazo es el de la responsabilidad extracontractual.","La responsabilidad extracontractual prescribe, en cambio, al año.","Ese plazo no corresponde a ninguna de las dos prescripciones previstas."]],
  "327": ["¿Desde cuándo corre la prescripción cuando quedan secuelas?",["Desde la fecha del alta hospitalaria del paciente afectado","Desde la fecha del acto que origina el daño","Desde el momento en que se conoce con precisión el alcance de las secuelas"],["El alta solo sirve de punto de partida cuando no quedan secuelas.","El punto de partida es el conocimiento de los efectos, no la fecha del acto.","La estabilización del estado, y no el alta hospitalaria, hace correr el plazo."]],
  "328": ["¿Qué conlleva la responsabilidad penal para el profesional?",["La obligación de cumplir una pena y de reparar los daños causados","La única obligación de indemnizar a la víctima del perjuicio sufrido","La única prohibición temporal de ejercer impuesta por el colegio"],["La pena puede ser prisión, multa o inhabilitación para el ejercicio.","La indemnización por sí sola caracteriza la responsabilidad civil.","La inhabilitación colegial corresponde al procedimiento disciplinario."]],
  "329": ["¿Cuál de estas infracciones no figura entre las que afectan al personal sanitario?",["La violación del secreto profesional y la alteración de datos confidenciales","La apropiación indebida cometida en perjuicio de un paciente vulnerable","El homicidio por imprudencia y las lesiones causadas por imprudencia"],["Esa infracción figura expresamente entre las enumeradas.","Las infracciones enumeradas contemplan en particular la omisión del deber de socorro, las lesiones por imprudencia y el fraude documental.","Esas infracciones se cuentan entre las que afectan al personal sanitario."]],
  "330": ["¿En qué se fundamenta la responsabilidad penal?",["En la sola producción de un daño en el curso de la asistencia","En el incumplimiento por el profesional de una obligación contractual","En una conducta punible cometida con dolo o por imprudencia"],["Un daño sin culpa no compromete la responsabilidad penal.","El incumplimiento contractual corresponde a la responsabilidad civil.","El dolo supone que el acto haya sido querido de forma voluntaria e intencionada."]],
  "331": ["¿Cómo se define la imprudencia?",["Actos cometidos sin diligencia ni precaución, causando así un perjuicio","Actos cometidos voluntariamente y de manera intencionada","Actos cometidos por un profesional carente del título exigido"],["Refleja la asunción de un riesgo excesivo y no autorizado.","Esa intención caracteriza el dolo y no la imprudencia.","Ese ejercicio sin título corresponde al intrusismo profesional."]],
  "332": ["¿Qué es la imprudencia grave?",["La omisión de la diligencia media que mostraría cualquier profesional","La omisión de las precauciones más elementales, inexcusable atendiendo al deber","La falta de los conocimientos necesarios para realizar correctamente el acto"],["Esa omisión caracteriza la imprudencia leve.","Se distingue de la imprudencia leve, que omite la diligencia media.","Esa falta de saber corresponde a la impericia."]],
  "333": ["¿Qué es la impericia como tipo de imprudencia?",["El incumplimiento de las reglas de actuación fijadas por la lex artis","La extralimitación del ámbito de competencia reglamentaria de la profesión","La falta de conocimientos, de destreza o de las capacidades exigidas para actuar"],["Ese incumplimiento constituye otro tipo de imprudencia profesional.","Esa extralimitación corresponde al intrusismo y no a la imprudencia.","Constituye uno de los tipos de imprudencia profesional identificados."]],
  "334": ["¿Con qué condición se persiguen los delitos por imprudencia?",["Mediante denuncia de la persona lesionada o de su representante legal","De oficio, en cuanto el ministerio fiscal tiene conocimiento de ellos","Mediante denuncia ante el colegio profesional al que pertenece el facultativo"],["Su persecución no se produce, por tanto, de oficio.","Esa persecución de oficio vale para ciertos delitos, pero no para la imprudencia.","El colegio tramita un procedimiento disciplinario, sin activar la acción penal."]],
  "335": ["¿Cuándo no compromete la responsabilidad un error de diagnóstico?",["Cuando el paciente no ha sufrido ningún perjuicio a causa de ese error","Cuando los signos disponibles no eran concluyentes y se ha seguido la lex artis","Cuando el diagnóstico se ha rectificado antes del inicio del tratamiento"],["La ausencia de perjuicio excluye la reparación sin exonerar el razonamiento culposo.","El profesional ha de haber actuado según sus conocimientos y empleado los medios apropiados.","La rectificación posterior no basta para excluir la responsabilidad."]],
  "336": ["¿Cuándo constituye el error de diagnóstico una culpa profesional?",["Cuando el diagnóstico emitido difiere del que sostiene un colega","Cuando el propio paciente había apuntado el diagnóstico correcto","Cuando los signos de la patología eran claramente identificables"],["Una divergencia de apreciación no es en sí misma constitutiva de culpa.","La hipótesis formulada por el paciente no determina la culpa del profesional.","La negligencia reside entonces en no haber emitido el diagnóstico que se imponía."]],
  "337": ["¿Qué consecuencia conlleva la omisión de una prueba pertinente?",["El profesional responde del resultado, incluso sin prueba de que el examen lo habría evitado","El profesional solo es responsable si se prueba que el examen habría evitado el daño","El profesional queda exonerado si el resultado habría sido idéntico de todos modos"],["El nexo de causalidad existe por el solo hecho de que ese examen no se realizó.","Esa prueba precisamente no se exige al paciente.","La responsabilidad se compromete aunque el resultado hubiera sido el mismo."]],
  "338": ["¿En qué único caso puede el profesional abandonar a sus pacientes?",["Cuando el paciente se niega a seguir las prescripciones que se le dan","En caso de riesgo grave, con un peligro real y objetivo para su persona","Cuando se ha roto la relación de confianza con la persona atendida"],["La negativa del paciente no autoriza a interrumpir la asistencia.","Debe además presentarse voluntariamente para prestarles auxilio.","La ruptura del vínculo no dispensa de garantizar la continuidad asistencial."]],
  "339": ["¿Qué obligaciones subsisten para el profesional en huelga?",["Queda liberado de sus obligaciones durante toda la duración del paro","Debe garantizar la totalidad de la asistencia programada como de ordinario","Sigue sujeto a sus obligaciones éticas y debe garantizar la asistencia urgente"],["La huelga nunca exonera de la obligación de garantizar la asistencia urgente.","Solo la asistencia urgente debe garantizarse imperativamente.","La huelga no suspende el deber de asistencia hacia los pacientes."]],
  "340": ["¿Cuál de estos elementos no se exige para que se consume el delito de omisión del deber de socorro?",["Que la omisión haya agravado el estado de la víctima","Que el auxilio pueda prestarse sin riesgo para uno mismo o para un tercero","Que la víctima esté desamparada y en peligro grave y manifiesto"],["La conducta sigue siendo punible aunque el auxilio hubiera resultado inútil.","Esa condición figura entre los elementos constitutivos del delito.","Esas características se cuentan entre los elementos exigidos."]],
  "341": ["¿Por qué sigue siendo punible la omisión aun si el auxilio hubiera sido inútil?",["Porque la ley presume que todo auxilio mejora el estado de la víctima","Porque lo que se sanciona es la indiferencia ante el peligro","Porque el profesional nunca puede valorar por sí solo la utilidad del socorro"],["Ninguna presunción de ese tipo fundamenta la incriminación.","La sanción vale incluso si la muerte era inevitable o el perjuicio irreductible.","La apreciación de la utilidad no es lo que justifica la represión."]],
  "342": ["¿Qué es el fraude documental en el ámbito sanitario?",["La omisión de informaciones importantes en la historia clínica del paciente","La transmisión de la historia a un tercero no autorizado a conocerla","La expedición de justificantes falsos o la falsificación de documentos clínicos"],["Una omisión no constituye la falsificación de un documento presentado como auténtico.","Esa transmisión corresponde a la violación del secreto profesional.","El profesional tiene la obligación de garantizar la autenticidad de las historias clínicas."]],
  "343": ["¿Cuál de estos elementos no constituye el delito de falsificación de documentos clínicos?",["La reiteración de la conducta en varias historias distintas","La intención de obtener una ventaja económica o de cualquier otra naturaleza","El perjuicio o el peligro que el uso del documento puede causar a otro"],["Los elementos exigidos son el documento falso, la intención de obtener una ventaja y el perjuicio al que se expone.","Justificar una ausencia no autorizada en el trabajo es un ejemplo de ello.","Ese riesgo para el destinatario forma parte de los elementos constitutivos."]],
  "344": ["¿Qué sanciones acompañan al fraude documental en el ámbito sanitario?",["Una simple multa administrativa impuesta por la autoridad sanitaria","Prisión e inhabilitación especial para el ejercicio de la profesión sanitaria","La retirada temporal de la inscripción en el colegio profesional"],["La gravedad de la infracción exige sanciones penales y profesionales.","La expedición de certificados falsos puede además justificar un despido disciplinario.","Esa medida disciplinaria no agota las sanciones en que se incurre."]],
  "345": ["¿Qué determina la deontología?",["Las tareas mínimas exigidas a los profesionales en el ejercicio de su actividad","Las conductas de excelencia hacia las que el profesional debe tender","Las reglas técnicas reconocidas por los expertos de un ámbito determinado"],["Se encuentra en general en forma escrita en los códigos deontológicos.","La búsqueda de la excelencia caracteriza a la ética, que apunta al máximo.","Ese conjunto de reglas del arte corresponde a la lex artis."]],
  "346": ["¿Qué es un colegio profesional?",["Una asociación que defiende los intereses materiales de los profesionales afiliados","Un organismo que agrupa en un territorio a todos los miembros de una misma profesión","Un servicio administrativo encargado de expedir las autorizaciones de ejercicio"],["La defensa de los intereses materiales corresponde al sindicato, no al colegio.","Asegura una forma de regulación de la profesión que reúne.","El colegio regula la profesión y no se confunde con la administración."]],
  "347": ["¿Qué distingue al colegio de un sindicato o de una asociación profesional?",["Es el único facultado para negociar las condiciones de retribución de los facultativos","Agrupa únicamente a los profesionales que ejercen por cuenta propia","La pertenencia es obligatoria y condiciona el ejercicio de la profesión"],["La negociación de las condiciones de ejercicio corresponde a las organizaciones sindicales.","Reúne a los facultativos cualquiera que sea su modalidad de ejercicio.","La inscripción en el colegio es una condición necesaria para ejercer."]],
  "348": ["¿Quién elabora los códigos deontológicos?",["Los colegios profesionales, que son también autoridad de regulación y de sanción","Las sociedades científicas, a partir de los datos adquiridos por la ciencia","El ministerio competente en sanidad, previa consulta a los profesionales"],["Sancionan a quienes se apartan de la deontología profesional.","Las sociedades científicas producen recomendaciones, no códigos deontológicos.","La elaboración corresponde a los colegios, aunque una norma pueda refrendarlos."]],
  "349": ["¿Para qué sirve un código deontológico?",["Fijar las tarifas aplicables a los actos realizados por los profesionales","Orientar a los profesionales y fundamentar la persecución de quienes actúan mal","Describir las técnicas que cada profesional está autorizado a practicar"],["La tarificación de los actos no corresponde al código deontológico.","Es a la vez un apoyo para el ejercicio y una base disciplinaria.","El ámbito de competencia lo fija la regulación de la profesión."]],
  "350": ["¿En qué niveles se apoya el colegio de fisioterapeutas en Francia?",["Un consejo nacional y delegaciones en cada centro sanitario","Un consejo europeo y consejos nacionales en cada Estado miembro","Un consejo nacional, consejos regionales y consejos departamentales"],["La organización territorial no desciende al nivel de los centros.","El colegio es una institución nacional, sin nivel europeo.","El consejo departamental es el representante de proximidad del colegio."]],
  "351": ["¿De quiénes se compone un consejo departamental del colegio?",["De fisioterapeutas por cuenta propia y asalariados elegidos por los profesionales del departamento","De representantes designados por la agencia regional de salud competente","De fisioterapeutas por cuenta propia exclusivamente, en razón de su independencia"],["Su composición refleja la diversidad de las modalidades de ejercicio.","Sus miembros son elegidos por sus pares y no designados por la administración.","Los asalariados forman parte de él en igual condición que los demás."]],
  "352": ["¿A quién se aplica el código deontológico de los fisioterapeutas?",["Solo a los facultativos que ejercen por cuenta propia en el territorio nacional","A todos los fisioterapeutas, por cuenta propia o asalariados, que ejercen","Solo a los facultativos inscritos en el colegio de su departamento"],["El código atañe igualmente a los profesionales asalariados.","Se impone a los facultativos colegiados y a quienes realizan un acto profesional.","Se impone también a quien realiza un acto profesional sin estar colegiado."]],
  "353": ["¿Cuál de estas partes no figura en el código deontológico de los fisioterapeutas?",["Los deberes entre colegas y hacia los miembros de otras profesiones","Los deberes generales y los deberes hacia los pacientes atendidos","Las modalidades de fijación de los honorarios y de su cobro"],["Esa parte figura expresamente en la estructura del código.","Esas dos partes abren el código deontológico.","El código trata de los deberes generales, de los deberes hacia los pacientes y entre colegas."]],
  "354": ["¿Cuál de estas responsabilidades tiene el fisioterapeuta hacia sus colegas?",["No interferir ni desacreditar el trabajo de los demás fisioterapeutas","Promover la salud pública y el acceso equitativo a la asistencia sanitaria","Participar en actividades de prevención y de educación sanitaria"],["Debe además mantener el respeto, la lealtad y la colaboración profesional.","Ese compromiso corresponde a las responsabilidades hacia la sociedad y la profesión.","Esa participación corresponde igualmente al deber hacia la sociedad."]],
  "355": ["¿Qué responsabilidad tiene el fisioterapeuta hacia la sociedad y la profesión?",["Contribuir a la formación de los estudiantes y de los colegas menos experimentados","Rechazar el intrusismo profesional y denunciarlo","Denunciar de manera responsable las prácticas no éticas constatadas"],["Esa contribución corresponde a las responsabilidades hacia los colegas.","Debe igualmente actuar sin aprovecharse de las situaciones de vulnerabilidad.","Esa denuncia figura entre los deberes hacia los colegas."]],
  "356": ["¿Hacia qué se orienta la ética profesional, por oposición a la deontología?",["Hacia el deber, mientras que la deontología se orienta hacia el bien","Hacia la sanción, mientras que la deontología propone motivaciones","Hacia el bien, mientras que la deontología se orienta hacia el deber"],["La oposición es exactamente la inversa de esta.","Es la deontología la que exige acciones y prevé posibles sanciones.","El deber debe sin embargo permanecer en contacto con el bien."]],
  "357": ["¿Qué distingue a la ética profesional de la deontología en cuanto a su carácter?",["Una no es exigible y propone motivaciones, la otra exige acciones","Una es escrita y sancionada, la otra corresponde al uso no formalizado","Una corresponde al derecho, la otra corresponde exclusivamente a la moral"],["La deontología es normativa y aprobada por un colectivo de profesionales.","Es la deontología la que es escrita, normativa y acompañada de sanciones.","La deontología se sitúa precisamente entre la moral y el derecho."]],
  "358": ["¿Cómo se distinguen la ética y la deontología en cuanto a su amplitud?",["La ética establece el mínimo exigible, la deontología apunta al máximo","La ética se interesa por el máximo, la deontología establece el mínimo obligatorio","Ambas fijan el mismo nivel de exigencia por vías diferentes"],["La inversión es completa respecto de la distinción admitida.","Una tiende hacia la excelencia, la otra fija el umbral exigible a todos.","Su diferencia reside precisamente en el nivel de exigencia que plantean."]],
  "359": ["¿A qué hace referencia directamente la ética profesional?",["Al modelo de acción compartido por el conjunto de una comunidad profesional","A las normas jurídicas que encuadran el ejercicio de la profesión","A la conciencia personal del profesional que ejerce"],["Ese papel de modelo colectivo es el de la deontología.","Las normas jurídicas corresponden al derecho, distinto de la ética profesional.","La deontología, en cambio, asume una función de modelo de acción dentro de una comunidad."]],
  "360": ["¿Cuál de estas exigencias caracteriza la ética del cuidado en fisioterapia?",["Movilizar todos los recursos y aspirar a la excelencia, no a la mediocridad","Aplicar estrictamente los protocolos validados por el centro asistencial","Limitar su intervención al ámbito estricto de sus competencias técnicas"],["Supone también ponerse en el lugar de la persona y compartir su vivencia.","El respeto de los protocolos no basta para definir la ética del cuidado.","El papel del fisioterapeuta no se limita a la aplicación de técnicas."]],
  "361": ["¿Qué debe abarcar el término de cuidados según este enfoque?",["El conjunto de los actos técnicos recogidos en la nomenclatura profesional","Estrategias que fomenten modos de vida saludables y reduzcan el impacto de la enfermedad","Únicamente la rehabilitación de la función alterada por la patología en cuestión"],["La nomenclatura delimita la prestación, no el sentido del cuidado.","El profesional debe considerar al ser humano en su globalidad.","Reducir el cuidado a la función afectada contradice el enfoque global."]],
  "362": ["¿Cuál de estas dimensiones no figura entre las que hay que tener en cuenta en el paciente?",["El hecho de que los procesos de enfermedad y de curación difieran de una persona a otra","La dimensión comunitaria, según la cual lo que afecta a uno afecta al otro","La situación laboral y el nivel de ingresos de la persona atendida"],["Esa singularidad forma parte de los elementos a considerar.","Esa interdependencia figura entre los elementos del enfoque.","Las dimensiones admitidas son física, mental, emocional y espiritual."]],
  "363": ["¿Qué comprende la historia clínica?",["El conjunto de los documentos asistenciales, con la identificación de los profesionales","Únicamente los informes redactados por el médico responsable del paciente","Únicamente los datos administrativos necesarios para la facturación de los actos"],["Reúne las informaciones consideradas esenciales para conocer el estado de salud de forma fiable.","Reúne los documentos de todos los profesionales que han participado en la asistencia.","Los datos administrativos no constituyen más que una pequeña parte de ella."]],
  "364": ["¿Cuál es el objetivo principal de la historia clínica?",["Permitir probar la calidad de la asistencia en caso de litigio posterior","Facilitar la asistencia sanitaria recogiendo los datos útiles para la atención","Permitir el seguimiento estadístico de la actividad realizada por el centro"],["El uso probatorio es una consecuencia, no la finalidad primera de la historia.","Deben permitir obtener informaciones fiables y actualizadas sobre el estado de salud.","La explotación estadística es secundaria respecto de la función asistencial."]],
  "365": ["¿Existe una historia clínica única por paciente?",["Sí: una historia única reúne toda la asistencia recibida por la persona","Sí, pero solo para la asistencia prestada en el sector público","No: existe una historia por cada profesional con el que el paciente se relaciona"],["No existe una historia clínica única que abarque el conjunto de las atenciones.","La distinción no depende del carácter público o privado del centro.","Cada historia reúne las informaciones ligadas a ese profesional determinado."]],
  "366": ["¿Qué mención debe llevar la historia en caso de asistencia derivada de malos tratos?",["La circunstancia de que la asistencia deriva de malos tratos a un menor","La identidad del presunto autor de los malos tratos sufridos por el niño","La comunicación dirigida a la autoridad judicial competente"],["Esa precisión se añade a las informaciones obligatorias de la historia.","La historia consigna la circunstancia, sin tener por misión establecer la culpabilidad.","La comunicación es un trámite distinto de la llevanza de la historia."]],
  "367": ["¿Cuál de estos elementos no forma parte del contenido mínimo de la historia?",["El consentimiento informado recabado del paciente antes del acto","El presupuesto estimativo de los actos que quedan a cargo del paciente","El informe de anestesia y el informe quirúrgico o de parto"],["Ese documento figura expresamente en el contenido mínimo.","El contenido mínimo abarca la anamnesis, la evolución, el consentimiento y el informe de alta.","Esos informes forman parte de las piezas que la historia debe contener."]],
  "368": ["¿Quién es titular de las informaciones contenidas en la historia clínica?",["El centro que ha recogido y archivado esas informaciones","El profesional que ha redactado los documentos que componen la historia","El paciente"],["El centro garantiza su conservación sin ser titular de ellas.","Quien la redacta conserva la reserva de sus anotaciones, pero no la titularidad.","La obligación de confidencialidad lo protege frente a todo acceso indebido a esos datos sensibles."]],
  "369": ["¿Quién se encarga de la gestión de las historias en los centros hospitalarios?",["La unidad de admisión y de documentación clínica","Cada servicio, para los pacientes que él mismo ha atendido","El delegado de protección de datos designado por el centro"],["Reúne las historias en un archivo único, bajo la responsabilidad de la dirección.","La gestión está centralizada en un archivo único.","El delegado vela por la conformidad del tratamiento, no por la gestión documental."]],
  "370": ["¿Cómo deben archivarse las historias?",["Exclusivamente en soporte informático, para garantizar su seguridad","Cualquiera que sea su soporte, garantizando seguridad, conservación y recuperación","En su formato de origen, a fin de preservar su valor probatorio"],["Ninguna obligación recae sobre un soporte determinado.","En papel, audiovisual o informático, el soporte importa menos que esas tres garantías.","La conservación no impone necesariamente el formato de origen."]],
  "371": ["¿Cuál es la duración mínima de conservación de los documentos clínicos?",["Diez años en los dos países desde la fecha del último acto","Toda la vida del paciente y después diez años tras su fallecimiento","Cinco años en España y veinte años en Francia, desde el fin del proceso"],["Las duraciones mínimas difieren claramente de un país a otro.","Solo determinados datos, como los relativos al nacimiento, escapan a la destrucción.","La duración debe además adaptarse a cada situación asistencial."]],
  "372": ["¿Qué destino se reserva a los datos relativos al nacimiento del paciente?",["No se destruyen, sino que se transfieren a los archivos definitivos tras el fallecimiento","Se destruyen al término de la duración mínima de conservación","Se entregan a los herederos del paciente tras su fallecimiento"],["Comprenden las pruebas destinadas a determinar la filiación con la madre.","Esos datos escapan precisamente a la destrucción.","Se transfieren a los archivos de la administración correspondiente."]],
  "373": ["¿Por qué motivos se conservan los documentos clínicos más allá del mínimo?",["Únicamente a petición del paciente que desea conservar constancia de ellos","Con fines judiciales, epidemiológicos, de investigación o de organización del sistema","Para permitir al centro justificar su facturación ante las entidades"],["La petición del paciente no es el motivo de esa conservación prolongada.","Su tratamiento debe entonces evitar en lo posible la identificación de las personas.","Las necesidades contables no figuran entre los motivos admitidos."]],
  "374": ["¿Quién, entre los profesionales asistenciales, tiene acceso a la historia de un paciente?",["El conjunto de los profesionales del centro, sujetos al secreto profesional","Los profesionales que atendieron al paciente en un ingreso anterior","Los profesionales del centro que realizan su diagnóstico o su tratamiento"],["El secreto no basta: el acceso supone una participación en la asistencia.","Un ingreso pasado no abre un derecho de acceso permanente a la historia.","La historia constituye para ellos un instrumento esencial para prestar una asistencia adecuada."]],
  "375": ["¿Con qué condición pueden las administraciones sanitarias acceder a los datos de identificación?",["Para prevenir un riesgo grave y a través de un profesional sujeto al secreto","Sin condición, siempre que ejerzan una misión de servicio público","Previa autorización del paciente afectado por los datos solicitados"],["El acceso se justifica por razones epidemiológicas o de protección de la salud pública.","El acceso está estrictamente delimitado y no se deriva de la sola misión pública.","El acceso por motivo de salud pública no supone esa autorización."]],
  "376": ["¿Con qué límite puede el personal administrativo acceder a la historia?",["Al conjunto de la historia, siempre que esté obligado a la confidencialidad","Únicamente a los datos ligados a las funciones que ejerce efectivamente","A ningún dato de la historia, reservada a los profesionales asistenciales"],["La confidencialidad no levanta la limitación del acceso a los datos pertinentes.","La extensión del acceso se mide por la función desempeñada, no por el estatuto.","Accede a los datos necesarios para el ejercicio de sus funciones."]],
  "377": ["¿Por qué accede el personal de inspección y de evaluación a las historias?",["Para verificar la regularidad de la facturación dirigida a las entidades pagadoras","Para seleccionar las historias destinadas a trabajos de investigación","Para controlar la calidad de la asistencia y el respeto de los derechos de los pacientes"],["El control previsto recae sobre la calidad y los derechos, no sobre la facturación.","La investigación es objeto de reglas de acceso distintas y anonimizadas.","Verifica también las demás obligaciones del centro con los usuarios y la administración."]],
  "378": ["¿Qué regla se impone para el acceso a la historia con fines de investigación o docencia?",["Separar los datos de identificación de los datos clínicos para garantizar el anonimato","Obtener la autorización previa de la autoridad de protección de datos","Limitar el acceso únicamente a las historias de los pacientes ya fallecidos"],["Esa separación puede dejarse de lado si el paciente ha consentido en que no se haga.","Ninguna autorización previa de ese tipo se exige para ese acceso.","La anonimización permite el acceso sin restricción ligada al fallecimiento."]],
  "379": ["¿Qué excepción se aplica a las investigaciones llevadas a cabo por las autoridades judiciales?",["El acceso está prohibido mientras el paciente no haya dado su consentimiento","La unión de los datos de identificación y clínicos puede considerarse imprescindible","El acceso se limita a los datos posteriores a la apertura de la investigación"],["La autoridad judicial no está obligada a recabar ese consentimiento.","Se aplican entonces las disposiciones adoptadas por los jueces en el procedimiento.","No se prevé ninguna limitación temporal de ese tipo."]],
  "380": ["¿Cuál es el derecho del paciente sobre su propia historia?",["Obtener su entrega definitiva y el original de todas las piezas","Exigir la supresión de las menciones que considera inexactas","Acceder a ella y obtener copia de los datos que en ella figuran"],["El centro conserva la historia; el paciente obtiene copia de ella.","La rectificación de los datos inexactos sigue el procedimiento previsto para los datos personales.","Su representante acreditado dispone del mismo derecho."]],
  "381": ["¿Qué límites acotan el derecho de acceso del paciente a su historia?",["La confidencialidad debida a terceros y la reserva de las anotaciones subjetivas","El acuerdo previo del conjunto de los profesionales que han atendido al paciente","El plazo de cinco años siguientes al fin del proceso asistencial de que se trate"],["Los profesionales que han participado en su elaboración pueden oponer esa reserva.","No se exige ningún acuerdo colectivo para ejercer ese derecho.","El derecho de acceso no queda encerrado en un plazo semejante."]],
  "382": ["¿Quién puede acceder a la historia de una persona fallecida?",["Toda persona que acredite un interés legítimo en consultar esa historia","Los allegados y las personas vinculadas de hecho, salvo prohibición del difunto","Únicamente los herederos designados en la sucesión del paciente fallecido"],["El acceso está reservado a los allegados y a las personas vinculadas de hecho.","El acceso de un tercero motivado por un riesgo para su salud se limita a los datos pertinentes.","La condición de heredero no es el requisito admitido aquí."]],
  "383": ["¿Qué informaciones no se comunican nunca al acceder a la historia de un difunto?",["Las relativas a los tratamientos administrados durante el último ingreso","Las elaboradas por profesionales ajenos al centro","Las que afectan a su intimidad, las anotaciones subjetivas o las que perjudican a terceros"],["Los datos terapéuticos no quedan excluidos por principio.","El origen del documento no condiciona su comunicación.","Esas tres categorías quedan excluidas de toda comunicación."]]
});
